MultiLanguageSpellData['de'][282825] = {name = "Streubombenhagel", additional_info = "100 Meter Reichweite\nSofort\n[q]Eure Zauber und Fähigkeiten haben eine Chance, eine Bombe auf Euer Ziel abzufeuern, die sich in 5 kleinere Bomben aufteilt, wenn sie ihrem Ziel nahe ist. Beim Auftreffen auf dem Boden fügt jede der kleinen Bomben allen Gegnern in der Nähe 179 Schaden zu.\n\n Erhöht Eure Ingenieurskunst von Kul Tiras oder Zandalar um 25."}
MultiLanguageSpellData['de'][282826] = {name = "Goblinischer Schockzauberschutz", additional_info = "30 Meter Reichweite\n{Sofort} {10 sek. Abklingzeit}\n[q]Umgibt den Zaubernden mit 3 Kugelblitzen, die eine Chance von 50% gewähren, Nahkampf- oder Distanzangreifern Naturschaden zuzufügen. Jedes Mal, wenn der Blitzschlagschild ausgelöst wird, wird ein Kugelblitz verbraucht. Der Schild endet nach Ablauf von bis Abbruch oder nachdem er 3-mal ausgelöst wurde.\n(Procchance: 50%, 3s Abklingzeit)"}
MultiLanguageSpellData['de'][282827] = {name = "Pa'kus Zorn", additional_info = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 8 sek.)\n[q]Der Boss schleudert Federkiele auf alle Ziele, die alle 5.2 Sek. 46 körperlichen Schaden verursachen, und stößt sie alle zurück. Je weiter das Ziel vom Zaubernden entfernt ist, desto mehr Schaden erleidet es."}
