MultiLanguageSpellData['de'][284219] = {name = "Schrumpfen", additional_info = "55 Meter Reichweite\n{Wirken in} {1.5 sek. 3 sek. Abklingzeit}\n[q]Verringert den verursachten Schaden und die hervorgerufene Heilung um 99%.\n\n Wenn ein Verbündeter auf Euch tritt, während Ihr geschrumpft seid, erleidet Ihr 13085 körperlichen Schaden und werdet für 1 Sek. betäubt."}
