MultiLanguageSpellData['de'][285381] = {name = "Urzorn", additional_info = "{25 Energie} {/ 1 zu 5 Combopunkte 8 Meter Reichweite}\nSofort\nBenötigt Katzengestalt\n[q]Finishing-Move, der sofort Schaden verursacht und alle Gegner innerhalb von 10 Metern mit 'Zerfetzen' belegt. Hält pro Combopunkt länger an:\n\n 1 Punkt: [(17.2% der Angriffskraft) * 2] plus 'Zerfetzen' für ( 2 * 2) Sek.\n 2 Punkte: [(17.2% der Angriffskraft) * 3] plus 'Zerfetzen' für ( 2 * 3) Sek.\n 3 Punkte: [(17.2% der Angriffskraft) * 4] plus 'Zerfetzen' für ( 2 * 4) Sek.\n 4 Punkte: [(17.2% der Angriffskraft) * 5] plus 'Zerfetzen' für ( 2 * 5) Sek.\n 5 Punkte: [(17.2% der Angriffskraft) * 6] plus 'Zerfetzen' für ( 2 * 6) Sek."}
MultiLanguageSpellData['de'][285382] = {name = "Seetangumwicklung", additional_info = "Sofort\n[q]Wickelt alle Kreaturen in der Nähe in entkräftenden Seetang und erhöht so ihren erlittenen Schaden um 10%. Bei Nichtspielercharakteren ist dieser Effekt stapelbar. Die Schadenserhöhung nimmt mit der Anzahl der Stapel ' Seetangwickel ' zu, die der Spielercharakter bei Ablauf des Effekts hatte."}
