MultiLanguageSpellData['de'][285639] = {name = "Vantusrune: Schlacht von Dazar'alor", additional_info = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Ultramarinblaue Tinte (30), Grünliche Tinte (10)\n[q]Erschafft eine Vantusrune: Schlacht von Dazar'alor.\nBeute von:\nSchlacht von Dazar'alor\n\nSchatz:\nSchlacht von Dazar'alor\n\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses der Schlacht von Dazar'alor ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\n45"}
MultiLanguageSpellData['de'][285640] = {name = "Vantusrune: Schlacht von Dazar'alor", additional_info = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Ultramarinblaue Tinte (28), Grünliche Tinte (8)\n[q]Verringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Schlacht von Dazar'alor.\nBeute von:\nSchlacht von Dazar'alor\n\nSchatz:\nSchlacht von Dazar'alor\n\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses der Schlacht von Dazar'alor ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\n45"}
