MultiLanguageSpellData['de'][290105] = {name = "Psychischer Schrei", additional_info = "3% von Grundmana\n{Sofort} {30 sek. Abklingzeit}\n[q]Stößt einen psychischen Schrei aus, der 5 Gegner innerhalb von 8 Metern in die Flucht schlägt und sie für 6 Sek. desorientiert. Erlittener Schaden kann den Effekt unterbrechen."}
