MultiLanguageSpellData['de'][290108] = {name = "Erneuerung", additional_info = "{1.8% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Erfüllt das Ziel mit Glauben an das Licht, wodurch es sofort um 2 Gesundheit sowie im Verlauf von 15 Sek. um weitere 9 Gesundheit geheilt wird."}
MultiLanguageSpellData['de'][290109] = {name = "Verzweifeltes Gebet", additional_info = "Sofort 1.5 min Abklingzeit\n[q]Erhöht 10 Sek. lang die maximale Gesundheit um 25% und heilt Euch sofort um diesen Wert."}
MultiLanguageSpellData['de'][290110] = {name = "Segenswort: Züchtigung", additional_info = "{2% von Grundmana} {30 Meter Reichweite}\nSofort 1 min Abklingzeit\n[q]Züchtigt das Ziel mit (112.5% der Zaubermacht) Heiligschaden und macht es handlungsunfähig . Hält 4 Sek. lang an.\n\nHeilig\n[q]Cooldown reduced by 4 sec when you cast Smite."}
MultiLanguageSpellData['de'][290111] = {name = "Segenswort: Epiphanie", additional_info = "{4% von Grundmana} {40 Meter Reichweite}\nSofort 1 min Abklingzeit\n[q]Lässt ein Wunder geschehen und heilt einen Verbündeten um 37 Gesundheit."}
MultiLanguageSpellData['de'][290112] = {name = "Verbindende Heilung", additional_info = "{2.9% von Grundmana} {40 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Heilt Euch, Euer Ziel und ein weiteres verbündetes Ziel innerhalb von 20 Metern um 5 Gesundheit.\n\nVerringert die verbleibende Abklingzeit von 'Segenswort: Epiphanie' und 'Segenswort: Heiligung' um 0 Sek."}
MultiLanguageSpellData['de'][290113] = {name = "Geläuterter Kern", additional_info = "Sofort\n[q]Sämtlicher erlittene Schaden um 90% verringert."}
MultiLanguageSpellData['de'][290114] = {name = "Geist der Erlösung", additional_info = "Sofort 3 min Abklingzeit\n[q]Der Priester verwandelt sich für 11 Sek. in einen Geist der Erlösung. Der Geist kann sich weder bewegen noch angreifen, noch kann er das Ziel von Zaubern oder Effekten sein. In dieser Gestalt kann der Priester jeglichen Heilzauber ohne irgendwelche Kosten wirken."}
