MultiLanguageSpellData['de'][290430] = {name = "Erdbeben", additional_info = "{50 Energie} {40 Meter Reichweite}\nSofort\n[q]Lässt die Erde innerhalb von 8 Metern um das Ziel erzittern und aufbrechen. Gegner erleiden im Verlauf von 6 Sek. 6 körperlichen Schaden und werden manchmal zu Boden gestoßen."}
MultiLanguageSpellData['de'][290431] = {name = "Erdbeben", additional_info = "100 Meter Reichweite\nSofort\n[q]Lässt die Erde innerhalb von 8 Metern um den Zielort erzittern und aufbrechen. Gegner erleiden im Verlauf von 6 Sek. [Zaubermacht * 0.5 * 6 * (1 + Vielseitigkeit) * 0.9 * 1 * 1 * 1 * 1 ] körperlichen Schaden und werden mit einer Chance von 5% zu Boden gestoßen. Mehrere Einsätze von 'Erdbeben' können sich überlappen.\n\nDieser Zauber wird gegen einen ausgewählten Zielort eingesetzt."}
MultiLanguageSpellData['de'][290432] = {name = "Erdbeben", additional_info = "100 Meter Reichweite\nSofort\n[q]Lässt die Erde innerhalb von 8 Metern um den Zielort erzittern und aufbrechen. Gegner erleiden im Verlauf von 6 Sek. [Zaubermacht * 0.5 * 6 * (1 + Vielseitigkeit) * 0.9 * 1 * 1 * 1 * 1 ] körperlichen Schaden und werden mit einer Chance von 5% zu Boden gestoßen. Mehrere Einsätze von 'Erdbeben' können sich überlappen.\n\nDieser Zauber wird gegen einen ausgewählten Zielort eingesetzt."}
