MultiLanguageSpellData['de'][295907] = {name = "Uralter Sturm", additional_info = "Sofort\n[q]Beschwört einen uralten Sturm um einen Sturmgeist im Auge des Sturms herum.\n\n Der Sturm schiebt Spielercharaktere vom Auge des Sturms weg und verursacht alle 2 Sek. 1493 Frostschaden. Dieser Frostschaden steigt mit der Dauer des Sturms an. Verringert zusätzlich den erlittenen Schaden von Azsharas Glanz um 99%.\n\n Solange der Sturm anhält, erscheinen kontinuierlich Sturmlinge im Auge des Sturms.\n\n Der Sturm lässt nach, sobald der Sturmgeist besiegt wird."}
MultiLanguageSpellData['de'][295908] = {name = "Psychotische Teilung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Za'qul spaltet sich auf und erschafft Spiegelbilder in verschiedenen Reichen, die Energie auf das Original kanalisieren. Bei Ablauf wird diese Energie freigesetzt und fügt Gegnern in allen Reichen 224196 Schattenschaden zu.\n\n Wenn Za'quls Spiegelbilder besiegt werden, wird ' Gedankenfraktur ' ausgelöst."}
MultiLanguageSpellData['de'][295909] = {name = "Psychotische Teilung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Za'qul spaltet sich auf und erschafft Spiegelbilder in verschiedenen Reichen, die Energie auf das Original kanalisieren. Bei Ablauf wird diese Energie freigesetzt und fügt Gegnern in allen Reichen 224196 Schattenschaden zu.\n\n Wenn Za'quls Spiegelbilder besiegt werden, wird ' Gedankenfraktur ' ausgelöst."}
