MultiLanguageSpellData['de'][299333] = {name = "Lebensblut", additional_info = "[q0]Azerit Essenz\n[q]Alle 1-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 18 lang bestehen bleibt.\n\n Lebensblutsplitter\n Der Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 12 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren."}
MultiLanguageSpellData['de'][299334] = {name = "Resonanz der Weltader", additional_info = "[q0]Azerit Essenz\nSofort 1 min Abklingzeit\n[q]Konzentriert Energie in das Herz von Azeroth und lässt 3 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 18 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\n Erhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 12 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren."}
MultiLanguageSpellData['de'][299335] = {name = "Fokussierte Energie", additional_info = "[q0]Azerit Essenz\n[q]Eure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [ 5 * (1.5)] Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen."}
MultiLanguageSpellData['de'][299336] = {name = "Fokussierter Azeritstrahl", additional_info = "[q0]Azerit Essenz\nWirken in 1.333 sek. 1.5 min Abklingzeit\n[q]Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden zuzufügen."}
MultiLanguageSpellData['de'][299337] = {name = "Fokussierte Energie", additional_info = "[q0]Azerit Essenz\n[q]Eure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [ 5 * (1.5)] Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen.\n\n Wenn Ihr keine Stapel von 'Fokussierte Energie' habt, gewährt Euer erster Einsatz eines Schadenszaubers oder einer Schadensfähigkeit Euch 3 Stapel."}
MultiLanguageSpellData['de'][299338] = {name = "Fokussierter Azeritstrahl", additional_info = "[q0]Azerit Essenz\nWirken in 1.333 sek. 1.5 min Abklingzeit\n[q]Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden zuzufügen. Kann aus der Bewegung heraus eingesetzt werden."}
MultiLanguageSpellData['de'][299342] = {name = "Kugelfisch", additional_info = "6 Meter Reichweite\nWirken in 2 sek.\n[q]Fügt Gegnern in der Nähe Naturschaden zu."}
MultiLanguageSpellData['de'][299343] = {name = "Reinigungsprotokoll", additional_info = "[q0]Azerit Essenz\nCa. 2 Procs pro Minute\n[q]MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n 'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu."}
MultiLanguageSpellData['de'][299344] = {name = "Schutzblase", additional_info = "{Sofort} {10 sek. Abklingzeit}\n[q]Gewährt 3 Sek. lang Unverwundbarkeit, entfernt alle Gift-, Krankheits- und Magieeffekte und heilt Euch um 35% Eurer maximalen Gesundheit."}
MultiLanguageSpellData['de'][299345] = {name = "Läuternde Druckwelle", additional_info = "[q0]Azerit Essenz\n40 Meter Reichweite\nSofort 1 min Abklingzeit\n[q]Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\n Alle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt."}
MultiLanguageSpellData['de'][299346] = {name = "Reinigungsprotokoll", additional_info = "[q0]Azerit Essenz\nCa. 2 Procs pro Minute\n[q]MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1.25) * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n 'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu."}
MultiLanguageSpellData['de'][299347] = {name = "Läuternde Druckwelle", additional_info = "[q0]Azerit Essenz\n40 Meter Reichweite\nSofort 1 min Abklingzeit\n[q]Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\n Wenn ein Gegner innerhalb des Strahls stirbt, wird Euer Schaden 8 Sek. lang um 10% erhöht.\n\n Alle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt."}
MultiLanguageSpellData['de'][299348] = {name = "Uralte Flamme", additional_info = "[q0]Azerit Essenz\nCa. 1.25 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch [ 351 * 5 * (1.25)] Feuerschaden im Verlauf von 10 Sek., Verbündete werden um [ 351 * 5 * (1.25)] Gesundheit im Verlauf von 10 Sek. geheilt."}
MultiLanguageSpellData['de'][299349] = {name = "Konzentrierte Flamme", additional_info = "[q0]Azerit Essenz\n40 Meter Reichweite\n{Sofort} {30 sek. Abklingzeit}\n1 Aufladung\n[q]Beschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen. Die Flammen fügen dem Ziel danach zusätzlich 75% des Schadens im Verlauf von 6 Sek. zu oder heilen es um diesen Wert.\n\n Immer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt."}
