MultiLanguageSpellData['de'][300140] = {name = "Anodisierte Deflektoren", additional_info = "{Sofort} {30 sek. Abklingzeit}\n[q]Gewährt 6 Sek. lang 163 Parieren und 116 Vermeidung. Danach stoßt Ihr eine Schockwelle vor Euch aus, die 679 körperlichen Schaden verursacht."}
MultiLanguageSpellData['de'][300141] = {name = "Kriegsstandarte der Horde", additional_info = "Sofort\n[q]Nimmt eine Kriegsstandarte der Horde auf. Verringert Eure Bewegungsgeschwindigkeit etwas.\n\n Bei Kampfbeginn wird das Banner entfernt."}
MultiLanguageSpellData['de'][300142] = {name = "Hyperfadengelenkbänder", additional_info = "Sofort 2 min Abklingzeit\n[q]Verringert die verbleibende Abklingzeit Eurer 3 zuletzt gewirkten Zauber um 5 Sek."}
MultiLanguageSpellData['de'][300143] = {name = "Vergoldete Supraleiter", additional_info = "[q]Wenn Ihr Naturschaden erleidet, werden Euer kritischer Trefferwert, Euer Tempo, Eure Meisterschaft und Eure Vielseitigkeit 60 Sek. lang um 18 erhöht."}
MultiLanguageSpellData['de'][300144] = {name = "Kriegsbanner der Horde", additional_info = "Sofort\n[q]Trägt ein Kriegsbanner der Horde. Kann während des Reitens benutzt werden.\n\n Bei Kampfbeginn wird das Banner entfernt."}
MultiLanguageSpellData['de'][300145] = {name = "Elektrostatische Induktion", additional_info = "20 Meter Reichweite\nSofort 1 min Abklingzeit\n[q]Verschießt einen stromführenden Draht auf einen Gegner, der im Verlauf von 8 Sek. 1642 Naturschaden verursacht, solange Ihr Euch nicht weiter als 20 Meter entfernt."}
MultiLanguageSpellData['de'][300146] = {name = "Schnappdrachentangpirscher", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Wenn ein Schnappdrache zubeißt, sind die Bisspuren selbst nicht zu beachtlich, doch wenn das Gift das Fleisch um die Wunde zerfrisst, wird es unangenehm.\"\nQuest:\nBraves Mädchen\nZone:\nNazjatar"}
MultiLanguageSpellData['de'][300147] = {name = "Tiefenkorallenschnappdrache", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Im Wasser ist dieser Schnappdrache ein leiser Jäger, doch auf dem Land kann er sich nicht gerade gut verbergen.\"\nQuest:\nGezähmte Wildheit\nZone:\nNazjatar"}
MultiLanguageSpellData['de'][300148] = {name = "Quest abbrechen", additional_info = nil}
MultiLanguageSpellData['de'][300149] = {name = "Leisegleiter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die von Natur aus in dieser Kreatur gespeicherten Gase ermöglichen es ihr, sowohl in den Tiefen zu überleben als auch in der Luft zu schweben.\"\nBeute von:\nLautlos\nZone:\nNazjatar"}
MultiLanguageSpellData['de'][300150] = {name = "Fabius", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n[q]\"Er erhebt sich aus dem Wasser, seine Flossen schwingen locker im Wind, die Sonne lässt seine Schuppen glitzern. Er ist einfach... fabihaft.\"\nBeute von:"}
MultiLanguageSpellData['de'][300151] = {name = "Tintengeschuppter Tiefensucher", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n[q]\"Gezeitenhengste jagen in Schwärmen, indem sie ihre Beute immer und immer wieder mit ihren muskulösen Brustkörben rammen.\"\nVerkäufer:\nMagor Geistbeuger\nZone:\nNazjatar\nKosten:\n150\n\nVerkäufer:\nDazzerian\nZone:\nNazjatar\nKosten:\n150"}
MultiLanguageSpellData['de'][300152] = {name = "Gezeitenhengst", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden."}
MultiLanguageSpellData['de'][300153] = {name = "Blutroter Gezeitenhengst", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n[q]\"Dank ihrer blutroten Färbung können diese Wesen sich ausgezeichnet zwischen Korallenformationen verstecken.\"\nVerkäufer:\nMrrl\nZone:\nNazjatar\nKosten:\n4\n2\n1"}
MultiLanguageSpellData['de'][300154] = {name = "Silberner Gezeitenhengst", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n[q]\"Der Gezeitenhengst und seine silbrigen Schuppen wurden von dem Glitzern der Beute in Eurer Tasche angezogen.\"\nBesonderes Ereignis:\nPlunderstorm"}
MultiLanguageSpellData['de'][300155] = {name = "Belebender Nebel", additional_info = "Wirken in 2 sek.\n[q]Ruft belebenden Nebel herbei, der Spielercharaktere innerhalb von 16 Metern heilt und dabei alle 1 Sek. 5% Gesundheit und Mana wiederherstellt. Hält 9 Sek. lang an."}
