MultiLanguageSpellData['de'][310484] = {name = "Nussknackergranate", additional_info = "Wirken in 2 sek.\nReagenzien:\nHandvoll Laestritbolzen (3), Poröses Scheuermittel (2), Laestriterz\nBeruf:\nIngenieurskunst der Schattenlande (10)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n30\n\n(2)\n[q2]Benutzen: Fügt allen Gegnern in einem Radius von 5 Metern 13939 Naturschaden zu. (5 Min Abklingzeit)\n51"}
MultiLanguageSpellData['de'][310485] = {name = "Schattenlandmine", additional_info = "Wirken in 2 sek.\nReagenzien:\nHandvoll Laestritbolzen (5), Poröses Scheuermittel (3), Laestriterz (3)\nBeruf:\nIngenieurskunst der Schattenlande (20)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n75\n\n(2)\n[q2]Benutzen: Platziert eine Mine auf dem Boden, die explodiert, wenn ein Gegner auf sie tritt. Dies fügt allen Gegnern innerhalb eines Radius von 5 Metern 13939 Schattenschaden zu und stößt sie zurück. (5 Min Abklingzeit)\nBenötigtIngenieurskunst der Schattenlande\n(1)"}
MultiLanguageSpellData['de'][310486] = {name = "Bombenbolawerfer", additional_info = "Wirken in 2 sek.\nReagenzien:\nNussknackergranate (3), Wurmdurchsetztes Getriebe , Poröses Scheuermittel (5), Zwielichtborke , Penumbrafaden (10)\nBeruf:\nIngenieurskunst der Schattenlande (30)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n15\n\n(2)\n[q2]Benutzen: Verschießt ein Paar aneinandergebundene Bomben direkt nach vorn, die sich um den ersten getroffenen Gegner wickeln, nach 5 Sek. explodieren und Gegnern in der Nähe dabei 13939 Feuerschaden zufügen. (5 Min Abklingzeit)\nBenötigtIngenieurskunst der Schattenlande\n(1)"}
MultiLanguageSpellData['de'][310490] = {name = "Schwungumverteilungsstiefel", additional_info = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nZeitlich gesegnete Sprungfeder (10), Handvoll Laestritbolzen (20), Phaedrumerz (10), Gramleder (15), Schleierstoff (20)\nBeruf:\nIngenieurskunst der Schattenlande (65)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n2\n75\n\nWird bei Benutzung gebunden\n[q2]Benutzen: Leitet einen beträchtlichen Teil des Fallschadens, den Ihr bei Eurem nächsten Sturz erleiden würdet, auf Gegner in der Nähe um. Hält 10 Sek. lang an.\n\n Kann nicht in Instanzen verwendet werden. (5 Min Abklingzeit)\nBenötigtIngenieurskunst der Schattenlande\n(1)\n[q]\"Ermöglicht Euch das Ausführen einer superheroischen Landung!\""}
MultiLanguageSpellData['de'][310492] = {name = "Gravimetrische Störkanone", additional_info = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe (3), Zeitlich gesegnete Sprungfeder (3), Handvoll Laestritbolzen (20), Poröses Scheuermittel (20), Soleniumerz (10), Heiliger Splitter (5)\nBeruf:\nIngenieurskunst der Schattenlande (60)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n2\n50\n\nWird bei Benutzung gebunden\n[q2]Benutzen: Destabilisiert die Schwerkraft um einen Zielort, was 10 Sek. lang die Bewegung von Gegnern in der Nähe behindert, sie in zufällige Richtungen schleudert oder sie in die Luft stößt...\n\n sofern keine Fehlzündung eintritt.\nBenötigtIngenieurskunst der Schattenlande\n(1)\n[q]\"Wird gelegentlich als \"Schwarzes-Loch-Kanone\" bezeichnet, was jedoch ein unzutreffender Name ist. Eigentlich ist es eher ein Artilleriegeschütz.\""}
MultiLanguageSpellData['de'][310493] = {name = "533L3N-F4LL3", additional_info = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe (3), Zeitlich gesegnete Sprungfeder (5), Handvoll Laestritbolzen (10), Phaedrumerz (10), Seelenstaub (5)\nBeruf:\nIngenieurskunst der Schattenlande (50)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n2\n\nWird bei Benutzung gebunden\n[q2]Benutzen: Platziert ein Eindämmungsgerät auf dem Boden, das nach seiner Scharfmachung aktiviert wird, wenn ein Gegner darauf tritt. Der Gegner wird dann für 1 Min. gebannt.\n\n Es sei denn, es tritt eine Fehlzündung ein.\n\n Verringerte Wirksamkeit gegen Spielercharaktere. (3 Min Abklingzeit)\nBenötigtIngenieurskunst der Schattenlande\n(1)\n[q]\"Mit wem werdet Ihr kommunizieren?!\""}
MultiLanguageSpellData['de'][310495] = {name = "Dimensionswechsler", additional_info = "Wirken in 2 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nWurmdurchsetztes Getriebe , Handvoll Laestritbolzen (10), Sinvyrerz (3), Umbryl , Unsterblichkeitssplitter\n[q]Bringt dauerhaft einen technomagischen Realitätsverzerrer an Eurem Gürtel an. Damit könnt Ihr Euch außerhalb des Kampfes unsichtbar machen.\nBeruf:\nIngenieurskunst der Schattenlande (45)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n75"}
MultiLanguageSpellData['de'][310496] = {name = "Elektrosprung", additional_info = "Wirken in 2 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nWurmdurchsetztes Getriebe , Handvoll Laestritbolzen (10), Soleniumerz (3), Oribrant , Unsterblichkeitssplitter\n[q]Bringt dauerhaft ein technomagisches Raumzeitfaltgerät an Eurem Gürtel an. Damit könnt Ihr Euch sofort über eine kurze Distanz in eine zufällige Richtung teleportieren.\nBeruf:\nIngenieurskunst der Schattenlande (45)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n75"}
MultiLanguageSpellData['de'][310497] = {name = "Schadensvergelter", additional_info = "Wirken in 2 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nWurmdurchsetztes Getriebe , Handvoll Laestritbolzen (10), Oxxeinerz (3), Wutauge , Unsterblichkeitssplitter\n[q]Bringt dauerhaft ein technomagisches Fluxrelais an Eurem Gürtel an. Dieses lässt bei Aktivierung mehrere kleine Klingenwaffen um Euch herumschweben, die Angreifern Schaden zufügen.\nBeruf:\nIngenieurskunst der Schattenlande (45)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n75"}
