MultiLanguageSpellData['de'][310501] = {name = "[q3]Flexible Ektoplasmabrille", additional_info = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe (3), Handvoll Laestritbolzen (5), Umbryl (2), Schleierstoff (10)\nOptionale Reagenzien:\nBeruf:\nIngenieurskunst der Schattenlande (85)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n5\n25\n\n[q3]Flexible Ektoplasmabrille\nWird beim Aufheben gebunden\nKopf Stoff\n12 Rüstung\n+18 Intelligenz\n+27 Ausdauer\n[q2]+ 18 Zufallswert 1\n[q2]+ 18 Zufallswert 2\nHaltbarkeit 85 / 85\n[q2]Anlegen: Erhöht Eure Ingenieurskunst der Schattenlande um 20.\n[q2]Benutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\n60\nBenötigtIngenieurskunst der Schattenlande\n(1)"}
MultiLanguageSpellData['de'][310504] = {name = "[q3]Geerdete Ektoplasmabrille", additional_info = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe (3), Handvoll Laestritbolzen (5), Umbryl , Oribrant , Gramleder (10)\nOptionale Reagenzien:\nBeruf:\nIngenieurskunst der Schattenlande (85)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n5\n25\n\n[q3]Geerdete Ektoplasmabrille\nWird beim Aufheben gebunden\nKopf Leder\n20 Rüstung\n+18 [Beweglichkeit oder Intelligenz]+27 Ausdauer\n[q2]+ 18 Zufallswert 1\n[q2]+ 18 Zufallswert 2\nHaltbarkeit 85 / 85\n[q2]Anlegen: Erhöht Eure Ingenieurskunst der Schattenlande um 20.\n[q2]Benutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\n60\nBenötigtIngenieurskunst der Schattenlande\n(1)"}
MultiLanguageSpellData['de'][310507] = {name = "[q3]Gegliederte Ektoplasmabrille", additional_info = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe (3), Handvoll Laestritbolzen (5), Wutauge , Umbryl , Gramleder (5), Bleicher Knochen (5)\nOptionale Reagenzien:\nBeruf:\nIngenieurskunst der Schattenlande (85)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n5\n25\n\n[q3]Gegliederte Ektoplasmabrille\nWird beim Aufheben gebunden\nKopf Kette\n29 Rüstung\n+18 [Beweglichkeit oder Intelligenz]+27 Ausdauer\n[q2]+ 18 Zufallswert 1\n[q2]+ 18 Zufallswert 2\nHaltbarkeit 85 / 85\n[q2]Anlegen: Erhöht Eure Ingenieurskunst der Schattenlande um 20.\n[q2]Benutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\n60\nBenötigtIngenieurskunst der Schattenlande\n(1)"}
