MultiLanguageSpellData['de'][311423] = {name = "[q2]Schriftstück der Grabräuberei", additional_info = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte , Umbraltinte , Dunkles Pergament\nBeruf:\nInschriftenkunde der Schattenlande (10)\nLehrer:\nSchreiber Au'tehshi\nZone:\nOribos\nKosten:\n30\n\n[q2]Schriftstück der Grabräuberei\n[q2]Benutzen: Ermöglicht das Öffnen von Schlössern, die eine Fertigkeit von bis zu 60 im Schlossknacken benötigen. Dieser Vorgang verbraucht die Schriftrolle.\n51\nBenötigtInschriftenkunde der Schattenlande\n(1)"}
MultiLanguageSpellData['de'][311424] = {name = "[q2]Kodex des ausgeglichenen Gemüts", additional_info = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte (7), Umbraltinte (7), Stille Tinte , Dunkles Pergament (75)\nVerkäuferin:\nAdjutantin Mikaros\nZone:\nOribos\nDie Aufgestiegenen - Freundlich\nKosten:\n8\n\nVerkäufer:\nAdjutantin Nikos\nZone:\nBastion\nDie Aufgestiegenen - Freundlich\nKosten:\n8\n\n[q2]Kodex des ausgeglichenen Gemüts\n51\n[q]\"Wird von Spielercharakteren erstellt, die den Beruf Inschriftenkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\""}
MultiLanguageSpellData['de'][311425] = {name = "[q0]Foliant des ausgeglichenen Gemüts", additional_info = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte (3), Umbraltinte (3), Dunkles Pergament (25)\nBeruf:\nInschriftenkunde der Schattenlande (15)\nLehrer:\nSchreiber Au'tehshi\nZone:\nOribos\nKosten:\n50\n\n[q0]Foliant des ausgeglichenen Gemüts\n51\n[q]\"Wird von Spielercharakteren erstellt, die den Beruf Inschriftenkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\""}
MultiLanguageSpellData['de'][311441] = {name = "[q3]Dunkelmond-Karte des Todes", additional_info = "Wirken in 2.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte (7), Umbraltinte (7), Stille Tinte , Dunkles Pergament\n[q]Stellt eine zufällige Dunkelmond-Karte aus dem Unbeugsamkeits-, Gier-, Fäulnis- oder Rastkartenset her. Stellt manchmal eine leere Karte her, mit der Ihr eine zufällige Karte aus einem bestimmten Set herstellen könnt.\nBeruf:\nInschriftenkunde der Schattenlande (80)\nLehrer:\nSchreiber Au'tehshi\nZone:\nOribos\nKosten:\n4\n\n[q3]Dunkelmond-Karte des Todes\n[q]\"Eine zufällige Dunkelmond-Karte des Todes. Sammelt das ganze Set, um eine Belohnung zu erhalten.\""}
MultiLanguageSpellData['de'][311444] = {name = "Unbeugsamkeitskartenset", additional_info = "Sofort 1.5 min Abklingzeit\n[q]Umgibt Euch mit einer Phalanx aus 5 Schilden. Angriffe gegen Euch zerstören einen Schild, was den durch den Angriff erlittenen Schaden um bis zu 1072 - 2145 verringert. Der Wert ist von der obenliegenden Karte des Kartensets abhängig. Hält 10 Sek. lang an."}
