MultiLanguageSpellData['de'][312748] = {name = "Restanima", additional_info = "Sofort\n[q][INTERNAL] Allows spawning of anima orbs"}
MultiLanguageSpellData['de'][312749] = {name = "Befreiung", additional_info = "[q0]Pakt-Fähigkeit\nWirken in 1.5 sek. 2 min Abklingzeit\n[q]Löst Euch in reine Anima auf, was Eure Bewegungsgeschwindigkeit auf 300% erhöht, Eure Fallgeschwindigkeit verringert und Euch vorwärtsbefördert. Hält 4 Sek. lang an.\n\n Verringert den Radius, in dem Gegner Euch entdecken, deutlich."}
MultiLanguageSpellData['de'][312750] = {name = "Alptraum anziehen", additional_info = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 1 min)\n[q]Der beschworene Alptraum macht sich zu seinem Schöpfer auf, um ihn mit Macht zu erfüllen."}
MultiLanguageSpellData['de'][312751] = {name = "Kralle von Ha-Li", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Ha-Lis Brut ist am blauen Himmel Pandarias zu Hause und jagt dort arglose Beute.\"\nBeute von:\nHa-Li\nZone:\nTal der Ewigen Blüten"}
MultiLanguageSpellData['de'][312752] = {name = "Eiskalt", additional_info = "20 Meter Reichweite\nSofort\n[q]Bewirkt alle 6 Sek. 'Raureif'."}
MultiLanguageSpellData['de'][312753] = {name = "Hoffnungsvernichtergargon", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Er war einst das treue Reittier eines Lordregenten des Hauses Dornfluch, stellte sich dann aber gegen ihn und sein Gefolge. Mitglieder von Haus Dornfluch munkeln nun über einen im Dunklen lauernden Gargon, der Venthyr auflauert, die sich in die finsteren Bereiche des Kelchdistrikts von Revendreth begeben.\"\nPakt:\nVenthyr\nZone:\nRevendreth"}
MultiLanguageSpellData['de'][312754] = {name = "Kampfgargon Vrednic", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Prinz Renathals treuer Gargon Vrednic begleitet ihn bereits seit Jahrtausenden. In seiner Sinvyrrüstung kann Vrednic allein durch sein Erscheinen alle in Angst und Schrecken versetzen, die ihn mit seinen Reiter in die Schlacht reiten sehen.\"\nPakt:\nVenthyr\nZone:\nRevendreth"}
MultiLanguageSpellData['de'][312756] = {name = "PH Phalynx", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei."}
MultiLanguageSpellData['de'][312758] = {name = "PH Epic Phalynx", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei."}
MultiLanguageSpellData['de'][312759] = {name = "Traumlichtrunenhirsch", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Runenhirsche werden jenen gewährt, die der Winterkönigin und dem Hof der Nacht ihre Dienste versichert haben.\"\nPakt:\nNachtfae\nZone:\nArdenwald"}
MultiLanguageSpellData['de'][312761] = {name = "Verzauberter Traumlichtrunenhirsch", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die majestätischen Runenhirsche sind mit ihren kunstvollen Geweihen in der Lage, dem Umgebungslicht des Ardenwalds Anima zu entziehen. Die Anima dient ihnen als Nahrung und verleiht ihnen Geschwindigkeit und Magie.\"\nPakt:\nNachtfae\nZone:\nArdenwald"}
MultiLanguageSpellData['de'][312762] = {name = "Schlundgebundener Seelenjäger", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Seelenjäger werden dazu eingesetzt, Seelen aufzuspüren, die sich vor ihrem dunklen Schicksal in die Einöden flüchten. Sie gehören zu den wenigen Kreaturen, die den Schlund ohne Unbehagen durchqueren.\"\nBeute:\nVollgefressener Schemenhund\nZone:\nDer Schlund"}
MultiLanguageSpellData['de'][312763] = {name = "Finsterbauhartpanzer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Das Chitin des Finsterbauhartpanzers ist robust genug, um Mörsergranaten und Drachenfeuer zu widerstehen. Falls nötig wird es praktischerweise auch alles verzehren, was keine Anima enthält.\"\nAbenteuer:\nShadowlands"}
