MultiLanguageSpellData['de'][312946] = {name = "Seelenverwandtschaft", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Erschafft eine Verbindung mit einem Verbündeten. Ihr könnt die Verbindung alle 1 Min. für 10 Sek. ermächtigen, was Euch einen Effekt abhängig von der Rolle Eures Partners und Eurem Partner einen Effekt abhängig von Eurer Rolle gewährt.\n\n [ Wächter : Tank\n Seelenschutz\nSchützt Euren verbundenen Partner und leitet 40% des von ihm erlittenen Schadens auf Euch um, sofern Ihr nicht unter 20% Gesundheit fallt. ] [ Wiederherstellung : Heiler\n Seelenfokus\nKonzentriert Euch auf Euren verbundenen Partner und dupliziert 30% Eurer sämtlichen hervorgerufenen Heilung auf ihn. /\n\nGleichgewicht, Wildheit\nSchadensverursacher\n Seelenermächtigung\nErfüllt Euren verbundenen Partner mit Energie und gewährt ihm so 20% Eures Schadens als zusätzlichen Arkanschaden, zusätzliche Heilung oder Absorption. ]"}
MultiLanguageSpellData['de'][312947] = {name = "Resonierender Pfeil", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Verschießt einen resonierenden Pfeil auf den Zielort, der Gegnern im Bereich (20% der Angriffskraft) Arkanschaden zufügt und den Bereich für 10 Sek. mit widerhallender Anima füllt. Der Effekt lässt Eure Angriffe die Sichtlinie zu Gegnern im Bereich ignorieren. Außerdem wird Eure kritische Trefferchance gegen sie um 30% erhöht.\n\n Auch nach Verlassen des Bereichs widerhallender Anima kann der Jäger noch 4 Sek. lang die Sichtlinie zum Gegner ignorieren."}
MultiLanguageSpellData['de'][312950] = {name = "Strahlender Funke", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Beschwört einen strahlenden Funken, der sofort (91.2% der Zaubermacht) Arkanschaden und im Verlauf von 10 Sek. zusätzlich (49.5% der Zaubermacht) Schaden verursacht.\n\n Das Ziel erleidet 10% mehr Schaden durch Eure direkten Schadenszauber, der bei jedem Treffer gestapelt wird. Dieser Effekt endet nach 4 Zaubern."}
MultiLanguageSpellData['de'][312951] = {name = "Waffen der Ordnung", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Braumeister\nErhöht für die nächsten 30 Sek. Eure Meisterschaft um ( 0.924000025 * 10)%. Zusätzlich wird die Abklingzeit von 'Fasshieb' sofort abgeschlossen und von 'Fasshieb' getroffene Gegner erleiden 10 Sek. lang 8% mehr Schaden durch Euch. Dieser Effekt ist bis zu 4-mal stapelbar.\n\nWindläufer\nErhöht für die nächsten 30 Sek. Eure Meisterschaft um ( 2.3287499 * 10)%. Zusätzlich verringert 'Tritt der aufgehenden Sonne' die Chikosten 5 Sek. lang um 1 und 'Blackout-Tritt' verringert die Abklingzeit betroffener Fähigkeiten um zusätzlich 1 Sek.\n\nNebelwirker\nErhöht für die nächsten 30 Sek. Eure Meisterschaft um ( 6.92999983 * 10)%. Zusätzlich wird die Abklingzeit von 'Essenzborn' sofort abgeschlossen und 'Essenzborn' heilt bis zu 6 Verbündete in der Nähe zu Beginn und am Ende der Kanalisierung um (40% der Zaubermacht) Gesundheit."}
MultiLanguageSpellData['de'][312952] = {name = "Göttlicher Glockenschlag", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Setzt abhängig von Eurer Spezialisierung sofort 'Heiliger Schock', 'Schild des Rächers' oder 'Richturteil' gegen bis zu 5 Ziele innerhalb von 30 Metern ein. [ Vergeltung : Das von 'Göttlicher Glockenschlag' ausgelöste 'Richturteil' verursacht 100% mehr Schaden ]"}
MultiLanguageSpellData['de'][312953] = {name = "Segen der Aufgestiegenen", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Gewährt 10 Sek. lang Kraft von den Aufgestiegenen, was Euch Zugriff auf ' Nova des Aufstiegs ' gewährt, [ Schatten : ' Gedankenschinden ' /\n\nDisziplin, Heilig\n' Heilige Pein ' ] durch ' Woge des Aufstiegs ' ersetzt und die Bewegungsgeschwindigkeit um 50% erhöht.\n\n Löst bei Ablauf ' Aufgestiegene Eruption ' aus:\n\nExplodiert und fügt abhängig von der Anzahl der Ziele Gegnern innerhalb von 15 Metern bis zu (210% der Zaubermacht) Arkanschaden zu und heilt Verbündete innerhalb dieses Radius um bis zu (159% der Zaubermacht) Gesundheit. Diese Werte erhöhen sich für jeden Stapel von 'Segen der Aufgestiegenen' um 3%."}
MultiLanguageSpellData['de'][312954] = {name = "Widerhallender Tadel", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Fügt einem Gegner (120% der Angriffskraft) Arkanschaden zu und extrahiert seine Anima, um einen Combopunkt für 45 Sek. mit Anima zu laden.\n\n Schaden verursachende Finishing-Moves, die eine Eurer Animaladung entsprechende Anzahl Combopunkte verbrauchen, funktionieren so, als ob sie 7 Combopunkte verbraucht hätten.\n\nGewährt 2 Combopunkte."}
MultiLanguageSpellData['de'][312955] = {name = "Vespertotem", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Beschwört ein Totem am Zielort, das 30 Sek. lang bestehen bleibt. Eure nächsten 3 Schadenszauber oder -fähigkeiten lassen das Totem (80% der Zaubermacht) Arkanschaden auf bis zu 6 Gegner in seiner Nähe abstrahlen und Eure nächsten 3 Heilzauber heilen bis zu 6 Verbündete in der Nähe des Totems um (91% der Zaubermacht) Gesundheit.\n\n Wenn Ihr diese Fähigkeit erneut einsetzt, während das Totem aktiv ist, ändert Ihr seine Position."}
MultiLanguageSpellData['de'][312956] = {name = "Geißelnder Obolus", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Verursacht sofort (65% der Zaubermacht) Arkanschaden sowie (108% der Zaubermacht) Arkanschaden im Verlauf von 18 Sek. Wenn der Gegner stirbt, während er mit 'Geißelnder Obolus' belegt ist, erzeugt Ihr [ Gebrechen : 5 / Dämonologie : 5 /\n\nZerstörung\n5 ] Seelensplitter. Wenn er überlebt, wird die Abklingzeit von 'Geißelnder Obolus' abgeschlossen."}
MultiLanguageSpellData['de'][312957] = {name = "Speer der Bastion", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Schleudert einen kyrianischen Speer an den Zielort, der sofort (110% der Angriffskraft) Arkanschaden und im Verlauf von 4 Sek. zusätzlich (120% der Angriffskraft) Schaden verursacht. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\n Getroffene Gegner werden für die Dauer an die Position des Speers der Bastion gebunden.\n\nErzeugt 25 Wut."}
