MultiLanguageSpellData['de'][314959] = {name = "Gebackene Leerenflosse", additional_info = "Wirken in 2 sek.\nReagenzien:\nAnomale Leerenflosse (8), Fragwürdiges Fleisch (3), Aromatisches Fischöl (3), Wildes Mehl (4)\n[q]Bereitet gebackene Leerenflosse zu.\nBeute von:\nKultisten von N'Zoth\n\n(5)\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt.\n\n Während Ihr satt seid, ist Eure Bewegungsgeschwindigkeit in Visionen von N'Zoth um 20% erhöht."}
MultiLanguageSpellData['de'][314960] = {name = "K'Bap", additional_info = "Wirken in 2 sek.\nReagenzien:\nFragwürdiges Fleisch (8), Missgestalteter Knirscher (5), Anomale Leerenflosse (3), Aromatisches Fischöl (3)\n[q]Bereitet K'Bap zu.\nBeute von:\nKultisten von N'Zoth\n\n(5)\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\n Wenn Ihr mehr als 10 Sek. mit Essen verbringt, stellt Ihr sofort 100 geistige Gesundheit wieder her. (3 Min Abklingzeit)"}
MultiLanguageSpellData['de'][314961] = {name = "Dubiose Delikatesse", additional_info = "Wirken in 2 sek.\nReagenzien:\nFragwürdiges Fleisch (8), Aromatisches Fischöl (3), Wildes Mehl (3), Frische Kartoffel (4)\n[q]Bereitet eine dubiose Delikatesse zu.\nBeute von:\nKultisten von N'Zoth\n\n(5)\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt.\n\n Während Ihr satt seid, wird die Dauer von erlittenen Kontrollverlusteffekten in Visionen von N'Zoth um 20% verringert."}
MultiLanguageSpellData['de'][314962] = {name = "Grässliches Gulasch", additional_info = "Wirken in 2 sek.\nReagenzien:\nFragwürdiges Fleisch (8), Anomale Leerenflosse (5), Missgestalteter Knirscher (3), Aromatisches Fischöl (3)\n[q]Bereitet grässliches Gulasch zu.\nBeute von:\nKultisten von N'Zoth\n\n(5)\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt.\n\n Während Ihr satt seid, regeneriert Ihr in Visionen von N'Zoth pro Sekunde 2% Eurer maximalen Gesundheit."}
MultiLanguageSpellData['de'][314963] = {name = "Gegrillter Knirscher", additional_info = "Wirken in 2 sek.\nReagenzien:\nMissgestalteter Knirscher (8), Fragwürdiges Fleisch (3), Aromatisches Fischöl (3), Fusaka (4)\n[q]Bereitet gegrillten Knirscher zu.\nBeute von:\nKultisten von N'Zoth\n\n(5)\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt.\n\n Während Ihr satt seid, nehmt Ihr für 10 Min. die Gestalt eines K'thir an, was die Entfernung verringert, aus der Gegner in einer Vision von N'Zoth Euch angreifen."}
