MultiLanguageSpellData['de'][320659] = {name = "Niyas Werkzeuge: Kletten", additional_info = "[q0]Seelenbandefähigkeit\nCa. 1.75 Procs pro Minute\n[q]Eure Schaden verursachenden Angriffe und Zauber haben eine Chance, Niyas Stachelkletten unter Euer Ziel zu werfen. Die Kletten bleiben am ersten Gegner haften, der sie durchschreitet, verringern seine Bewegungsgeschwindigkeit um 20% und fügen ihm im Verlauf von 6 Sek. [(Angriffskraft * 0.3312 * (1 + Vielseitigkeit)) * 6] Naturschaden zu."}
MultiLanguageSpellData['de'][320660] = {name = "Niyas Werkzeuge: Gift", additional_info = "[q0]Seelenbandefähigkeit\n[q]Eure Unterbrechungen wenden Niyas betäubendes Gift auf Euer Ziel an, was ihm im Verlauf von 30 Sek. [(Angriffskraft * 0.05 * (1 + Vielseitigkeit)) * 30] Naturschaden zufügt. Mit Niyas betäubendem Gift belegte Ziele erleiden bei einer erneuten Unterbrechung zusätzlich [Angriffskraft * 0.24 * (1 + Vielseitigkeit)] Naturschaden."}
MultiLanguageSpellData['de'][320661] = {name = "Ansturm", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Sobald Xav 100 Energie erreicht hat, zwingt er Spielercharaktere in die Duellgrube hinab. Der Sieger des Duells erhält ' Verherrlicht ', der Verlierer erleidet ' Blutig geschlagen '.\n\n Spielercharaktere erhalten alle 1 Sek. einen Stapel von ' Ruhmreicher Kampf '.\n\n Wird keiner der Spielercharaktere innerhalb von 45 Sek. besiegt, werden beide mit ' Feigheit ' belegt."}
