MultiLanguageSpellData['de'][320785] = {name = "Überwältigende Macht", additional_info = "100 Meter Reichweite\nSofort\n[q]Millhaus beschwört einen Machtkristall, der in Richtung von Millhaus kanalisiert und je nachdem, wer zuerst getroffen wird, entweder Spielercharaktere oder Millhaus beeinflusst.\n\n 'Überwältigende Macht' fügt betroffenen Spielercharakteren alle 1 Sek. 96978 Arkanschaden zu und erhöht ihren verursachten Schaden um 2%. Dieser Effekt hält 3 Sek. lang an und ist stapelbar.\n\n Wenn Millhaus von 'Überwältigende Macht' betroffen ist, wird sein verursachter Schaden 3 Sek. lang um 4% erhöht und ' Überwältigende Kraft! ' ausgelöst. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][320786] = {name = "Überwältigende Macht", additional_info = "100 Meter Reichweite\nSofort\n[q]Millhaus beschwört einen Machtkristall, der in Richtung von Millhaus kanalisiert und je nachdem, wer zuerst getroffen wird, entweder Spielercharaktere oder Millhaus beeinflusst.\n\n 'Überwältigende Macht' fügt betroffenen Spielercharakteren alle 1 Sek. 96978 Arkanschaden zu und erhöht ihren verursachten Schaden um 2%. Dieser Effekt hält 3 Sek. lang an und ist stapelbar.\n\n Wenn Millhaus von 'Überwältigende Macht' betroffen ist, wird sein verursachter Schaden 3 Sek. lang um 4% erhöht und ' Überwältigende Kraft! ' ausgelöst. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][320787] = {name = "Machtkristall beschwören", additional_info = "100 Meter Reichweite\nWirken in 1 sek.\n[q]Millhaus beschwört einen Machtkristall, der in Richtung von Millhaus kanalisiert und je nachdem, wer zuerst getroffen wird, entweder Spielercharaktere oder Millhaus beeinflusst.\n\n 'Überwältigende Macht' fügt betroffenen Spielercharakteren alle 1 Sek. 96978 Arkanschaden zu und erhöht ihren verursachten Schaden um 2%. Dieser Effekt hält 3 Sek. lang an und ist stapelbar.\n\n Wenn Millhaus von 'Überwältigende Macht' betroffen ist, wird sein verursachter Schaden 3 Sek. lang um 4% erhöht und ' Überwältigende Kraft! ' ausgelöst. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][320788] = {name = "Frostige Fesseln", additional_info = "100 Meter Reichweite\n{Wirken in} {2 sek. 3 sek. Abklingzeit}\n[q]Nalthor entfesselt frostige Tentakel, die einen zufälligen Spielercharakter bis zu 12 Sek. lang binden, ihn so bewegungsunfähig machen und ihm alle 2 Sek. 2424449 Frostschaden zufügen.\n\n Bei Ablauf breitet sich dieser Effekt auf alle Spielercharaktere innerhalb von 16 Metern aus."}
