MultiLanguageSpellData['de'][320869] = {name = "Lichtberührte Überreste", additional_info = "[q0]Animabonus\nSofort\n[q]Verringert die Manakosten von 'Blitzheilung' um 30%."}
MultiLanguageSpellData['de'][320870] = {name = "Blitzechofokus", additional_info = "[q0]Animabonus\nSofort\n[q]Der Effekt von [ Heilig : 'Blitzheilung' /\n\nDisziplin, Schatten\n'Schattenheilung' ] wird nach 4 Sek. wiederholt und heilt um 50% des ursprünglichen Werts."}
MultiLanguageSpellData['de'][320871] = {name = "Eifer des Vandalen", additional_info = "[q0]Animabonus\nSofort\n[q]Wenn Ihr ein zerstörbares Objekt in Torghast zerstört, wird Euer nächster Einsatz von [ Heilig : 'Heiliges Feuer' /\n\nDisziplin, Schatten\n'Gedankenschlag' ] um 3% verstärkt. Bis zu 40-mal stapelbar."}
MultiLanguageSpellData['de'][320872] = {name = "[q3]Blitzkiste", additional_info = "[q0]Animabonus\nSofort\n[q]Pro 30 Sek., in denen Ihr 'Blitzheilung' nicht einsetzt, wird die Heilung Eures nächsten Einsatzes von 'Blitzheilung' um 100% erhöht. Dieser Effekt ist bis zu 6-mal stapelbar."}
MultiLanguageSpellData['de'][320873] = {name = "Sengende Laterne", additional_info = "[q0]Animabonus\nSofort\n[q]Euer Zauber 'Blitzheilung' belegt das Ziel mit 'Sengendes Leuchten', wodurch es 20 Sek. lang 50% des erlittenen Schadens als Heiligschaden auf Angreifer reflektiert."}
MultiLanguageSpellData['de'][320874] = {name = "Segen des gefallenen Priesters", additional_info = "[q0]Animabonus\nSofort\n[q]Disziplin\n Wenn Ihr 'Gedankenschlag' einsetzt, wird der Schaden oder die Heilung Eures nächsten Einsatzes von 'Sühne' um 30% erhöht. Dieser Effekt ist stapelbar, aber die Dauer wird nicht zurückgesetzt.\n\nSchatten\n Wenn Ihr 'Gedankenschlag' einsetzt, wird der Schaden oder die Heilung Eures nächsten Einsatzes von 'Verschlingende Seuche' um 30% erhöht. Dieser Effekt ist stapelbar, aber die Dauer wird nicht zurückgesetzt.\n\nHeilig\n Wenn Ihr 'Heiliges Feuer' einsetzt, wird der Schaden oder die Heilung Eures nächsten Einsatzes von 'Segenswort: Züchtigung' um 60% erhöht. Dieser Effekt ist stapelbar, aber die Dauer wird nicht zurückgesetzt.\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][320875] = {name = "Verzehrender Refrain", additional_info = "[q0]Animabonus\nSofort\n[q]Der regelmäßige Schaden von 'Heiliges Feuer' hält 4 Sek. länger an."}
MultiLanguageSpellData['de'][320876] = {name = "Trunk des heiligen Feuers", additional_info = "[q0]Animabonus\nSofort\n[q]'Heiliges Feuer' hat eine Chance von 50%, keine Abklingzeit auszulösen."}
MultiLanguageSpellData['de'][320877] = {name = "Mal des rechtschaffenen Schutzes", additional_info = "[q0]Animabonus\nSofort\n[q]Während ein Gegner innerhalb von 10 Metern von Eurem Effekt 'Heiliges Feuer' betroffen ist, erleidet Ihr 35% weniger Schaden."}
MultiLanguageSpellData['de'][320878] = {name = "Heiliger Höllenstein", additional_info = "[q0]Animabonus\nSofort\n[q]Wenn 'Heiliges Feuer' abläuft, springt es auf ein anderes Ziel in der Nähe über."}
MultiLanguageSpellData['de'][320879] = {name = "Ideenverschlinger", additional_info = "[q0]Animabonus\nSofort\n[q]Kritische Treffer mit 'Gedankenschlag' gewähren [ Schatten : 20 Wahnsinn /\n\nDisziplin, Heilig\n1000 Mana ]"}
MultiLanguageSpellData['de'][320880] = {name = "Schmerzrad", additional_info = "[q0]Animabonus\nSofort\n[q]Erhöht die Dauer von [ Läuterung des Bösen : 'Läuterung des Bösen' / 'Schattenwort: Schmerz'] um 3 Sek. und erhöht den Schaden des Zaubers um 25%."}
MultiLanguageSpellData['de'][320881] = {name = "[q2]Schattenbeute", additional_info = "[q0]Animabonus\nSofort\n[q]Wenn 'Schattenwort: Schmerz' abläuft, werden alle Gruppenmitglieder innerhalb von 20 Metern um das betroffene Ziel um 10% ihrer maximalen Gesundheit geheilt."}
MultiLanguageSpellData['de'][320882] = {name = "[q3]Rotglühende Gedankenpikser", additional_info = "[q0]Animabonus\nSofort\n[q]Der Initialschaden von 'Schattenwort: Schmerz' trifft immer kritisch."}
MultiLanguageSpellData['de'][320883] = {name = "[q2]Rattenkadaversack", additional_info = "[q0]Animabonus\nSofort\n[q]Das Töten einer Schlundratte gewährt Euch eine zusätzliche Aufladung von 'Schattenwort: Tod'.\n\n Der Sack kann bis zu 28 tote Schlundratten fassen."}
MultiLanguageSpellData['de'][320884] = {name = "[q3]Impulsor", additional_info = "[q0]Animabonus\nSofort\n[q][ Heiliges Feuer : 'Heiliges Feuer' / 'Gedankenschlag'] macht das Ziel benommen, was seine Bewegungsgeschwindigkeit und Trefferchance 1 Min. lang um 20% verringert.\n\n Dieser Effekt wird durch nachfolgende Einsätze von 'Gedankenschlag' oder 'Heiliges Feuer' entfernt."}
MultiLanguageSpellData['de'][320885] = {name = "[q3]Modifizierter Impulsor", additional_info = "[q0]Animabonus\nSofort\n[q]Der Einsatz von [ Heiliges Feuer : 'Heiliges Feuer' / 'Gedankenschlag'] hebt den Effekt 'Geblendet' nicht mehr auf."}
MultiLanguageSpellData['de'][320886] = {name = "[q3]Katharstift", additional_info = "[q0]Animabonus\nSofort\n[q]20% Eures sämtlichen erlittenen Schadens wird im Katharstift gespeichert. Der Initialschaden Eures nächsten Einsatzes von 'Schattenwort: Schmerz' fügt Eurem Ziel den gespeicherten Schaden zu."}
MultiLanguageSpellData['de'][320887] = {name = "[q4]Schmerzbrechender Psalm", additional_info = "[q0]Animabonus\nSofort\n[q]'Schattenwort: Tod' verbraucht Euren Effekt [ Läuterung des Bösen : 'Läuterung des Bösen' / 'Schattenwort: Schmerz'] auf dem Ziel und fügt ihm den gesamten verbleibenden Schaden zu."}
MultiLanguageSpellData['de'][320888] = {name = "Gedankenexplodierer", additional_info = "[q0]Animabonus\nSofort\n[q]Erhöht den Schaden von 'Gedankenschlag' um 500%, die Abklingzeit der Fähigkeit aber auch um 400%."}
