MultiLanguageSpellData['de'][320890] = {name = "Psychischer Taschendiebstahl", additional_info = "[q0]Animabonus\nSofort\n[q]Der Einsatz von 'Gedankenkontrolle' bei einem Gegner leert dessen Taschen und gewährt Euch ungefähr 15 Phantasma."}
MultiLanguageSpellData['de'][320891] = {name = "[q2]Gebot der Ansteckung", additional_info = "[q0]Animabonus\nSofort\n[q]Der Einsatz von 'Gedankenkontrolle' bei einer Schlundratte löst 'Schnelle Ansteckung' aus, wodurch alle Schlundratten innerhalb von 15 Metern 2 bis 5 weitere Schlundratten gebären."}
MultiLanguageSpellData['de'][320892] = {name = "[q3]Fäden des Strippenziehers", additional_info = "[q0]Animabonus\nSofort\n[q]'Gedankenkontrolle' hält 30 Sek. länger an und erhöht den Schaden des Ziels um 50%."}
