MultiLanguageSpellData['de'][320894] = {name = "Animagriff", additional_info = "[q0]Animabonus\nSofort\n[q]Casting Thoughtsteal on a target has a chance to grant you a Maw Power.  This effect can only occur once per level.\n\n NYI - Grants 3% all stats.\n(Procchance: 20%)"}
MultiLanguageSpellData['de'][320895] = {name = "Dicke Juteschärpe", additional_info = "[q0]Animabonus\nSofort\n[q]'Machtwort: Seelenstärke' erhöht die Ausdauer zusätzlich um 10%."}
