MultiLanguageSpellData['de'][320898] = {name = "Schriftrolle des Suchers", additional_info = "[q0]Animabonus\nSofort\n[q]Wenn Ihr ein Aschenes Phylakterium zerstört, wird der Schaden von 'Feuerball', 'Frostblitz' oder 'Arkanschlag' um 2% erhöht. Dieser Effekt ist bis zu 100-mal stapelbar."}
MultiLanguageSpellData['de'][320899] = {name = "Zauberstabschmierfett", additional_info = "[q0]Animabonus\nSofort\n[q]Die Zauberzeit von [ Arkan (Level 10) : 'Arkanschlag' / Feuer : 'Feuerball' / Frost : 'Frostblitz' ] wird um 0.3 Sek. verringert."}
