MultiLanguageSpellData['de'][320901] = {name = "[q2]Hut des huschenden Zauberers", additional_info = "[q0]Animabonus\nSofort\n[q]Wenn Ihr eine Kreatur mit [ Arkan (Level 10) : 'Arkane Explosion' / Feuer : 'Flammenstoß' / Frost : 'Blizzard' ] tötet, wird Euer Tempo 15 Sek. lang um 10% erhöht. Bis zu 10-mal stapelbar."}
MultiLanguageSpellData['de'][320902] = {name = "[q3]Gravur des Bombardiers", additional_info = "[q0]Animabonus\nSofort\n[q]Arkan\n Wenn Ihr einem Gegner mit 'Arkane Explosion' Schaden zufügt, wird automatisch 'Prismatische Barriere' angewendet. Dieser Effekt kann nur einmal alle 20 Sek. auftreten.\n\nFrost\n Wenn Ihr einem Gegner mit 'Blizzard' Schaden zufügt, wird automatisch 'Eisbarriere' angewendet. Dieser Effekt kann nur einmal alle 20 Sek. auftreten.\n\nFeuer\n Wenn Ihr einem Gegner mit 'Flammenstoß' Schaden zufügt, wird automatisch 'Lodernde Barriere' angewendet. Dieser Effekt kann nur einmal alle 20 Sek. auftreten.\n(20s Abklingzeit)"}
MultiLanguageSpellData['de'][320903] = {name = "[q3]Einladung des Chaos", additional_info = "[q0]Animabonus\nSofort\n[q]Euer erster Einsatz von pro Stock verursacht zusätzlich 850% Schaden."}
