MultiLanguageSpellData['de'][320921] = {name = "[q2]Runenstoffbandagen", additional_info = "[q0]Animabonus\nSofort\n[q]Wenn Ihr beim Wirken von 'Arkanschlag', 'Feuerball' oder 'Frostblitz' unsichtbar seid, erhöht sich der Schaden des Effekts um 500%."}
MultiLanguageSpellData['de'][320922] = {name = "[q3]Gekritzel des verrückten Magiers", additional_info = "[q0]Animabonus\nSofort\n[q]Zu Beginn jedes Stocks erhaltet Ihr eine Eingebung, die Euch eine Reihenfolge bestimmter Zauber vermittelt.\n\n Wenn Ihr diese Zauber erfolgreich in der richtigen Reihenfolge wirkt, wird Eure Intelligenz um 5% erhöht."}
