MultiLanguageSpellData['de'][320930] = {name = "[q3]Finsterstimmensignet", additional_info = "[q0]Animabonus\nSofort\n[q][ Gebrechen : 'Dunkelblick beschwören' / Dämonologie : 'Dämonischen Tyrannen beschwören' / Zerstörung : 'Höllenbestie beschwören' ] beschwört 1 zusätzlichen Dämon."}
