MultiLanguageSpellData['de'][320940] = {name = "Auge von Endereth", additional_info = "[q0]Animabonus\nSofort\n[q]Erhöht den Schaden Eures nächsten Einsatzes von 'Verderbnis' für jede befreite Seele in Eurem Besitz um 10%, bis zu einem Maximum von 250%."}
