MultiLanguageSpellData['de'][322098] = {name = "Tod und Wahnsinn", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Ihr ein Ziel mit 20% oder weniger Gesundheit durch 'Schattenwort: Tod' nicht tötet, wird die Abklingzeit abgeschlossen. Kann nur einmal alle 10 Sek. auftreten. [ Schatten : Wenn ein Ziel innerhalb von 7 Sek. stirbt, nachdem Ihr es mit 'Schattenwort: Tod' getroffen habt, erhaltet Ihr 8 Wahnsinn ]"}
