MultiLanguageSpellData['de'][322101] = {name = "Schadensumleitung", additional_info = "{15 {Energie / 1.4% von Grundmana} 100 Meter Reichweite}\n{Sofort} {15 sek. Abklingzeit}\n[q]Nebelwirker ( Nebelwirkermönch )\n Stößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 25% des geheilten Werts als Naturschaden zufügt.\n\n Braumeister, Windläufer\n Stößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 10% des geheilten Werts als Naturschaden zufügt. [ Schadensumleitung : Entzieht all Euren heilenden Sphären positives Chi, um die Heilung durch 'Schadensumleitung' zu erhöhen ] [ Schadensumkehr : Erzeugt [(120% der Zaubermacht) + 30] Chi. ]"}
MultiLanguageSpellData['de'][322102] = {name = "Schadensumleitung", additional_info = "[q]Die Abklingzeit ist um 10 Sek. verringert und das positive Chi aller Eurer heilenden Sphären wird herangezogen, um die Heilung von 'Schadensumleitung' zu erhöhen."}
MultiLanguageSpellData['de'][322103] = {name = "Liebkosung des Lichts", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Sobald Verbündete den Effekt Eures Zaubers 'Machtwort: Barriere' erhalten, werden sie um (100% der Zaubermacht) Gesundheit geheilt. Wenn sie sich bei Ablauf des Effekts im Wirkungsbereich befinden, werden sie erneut um (100% der Zaubermacht) Gesundheit geheilt."}
MultiLanguageSpellData['de'][322104] = {name = "Schadensumleitung", additional_info = "[q]'Schadensumleitung' profitiert von 'Meisterschaft: Nebelschwall'."}
MultiLanguageSpellData['de'][322105] = {name = "Schattenbündnis", additional_info = "30 Meter Reichweite\nSofort\nBenötigt Schattengestalt\n[q]Beim Einsatz Eures [ Geistbeuger : Geistbeugers / Schattengeists] geht Ihr einen schattenhaften Pakt ein, der 'Strahlenkranz', 'Göttlicher Stern' und 'Sühne' in Schattenzauber verwandelt sowie den Schaden und die Heilung Eurer Schattenzauber um [ Geistbeuger : 10 / 25 ]% erhöht, solange dieser aktiv ist."}
MultiLanguageSpellData['de'][322109] = {name = "Berührung des Todes", additional_info = "Nahkampfreichweite\nSofort 3 min Abklingzeit\n[q]Ihr nutzt die größte Schwachstelle des gegnerischen Ziels aus und fügt ihm sofort Schaden in Höhe von 100% Eurer maximalen Gesundheit zu [ Verbesserte Berührung des Todes : wenn es sich um eine Kreatur handelt, die über weniger Gesundheit verfügt als Ihr / .\n\n Kann nur gegen Kreaturen eingesetzt werden, die weniger Gesundheit haben als Ihr.] [ Fügt Spielercharakteren sowie stärkeren Kreaturen mit weniger als 15% Gesundheit Schaden in Höhe von 35% Eurer maximalen Gesundheit zu ] [ Berührung des Todes : Verringert den gestaffelten Schaden um 200% des verursachten Schadens ] [ Erzeugt 3 Chisphären, die jeweils 1 Chi erzeugen, wenn Ihr durch sie lauft ] [ Erhöht den körperlichen Schaden des Mönchs für 10 Sek. um 15% ]"}
