MultiLanguageSpellData['de'][325064] = {name = "Sünden und Leid", additional_info = "Unbegrenzte Reichweite\n{Sofort} {5 sek. Abklingzeit}\n[q]Extrahiert die Sünden der Vergangenheit von zufälligen Gegnern an zufälligen Positionen.\n\n Sünden der Vergangenheit fügen dem nächsten Spielercharakter kontinuierlich 3555 Schattenschaden zu, bis sie mit den Strahlen von 'Geteiltes Leid' verbunden werden."}
MultiLanguageSpellData['de'][325065] = {name = "Ansturm der Wilden Jagd", additional_info = "[q0]Seelenbandefähigkeit\n[q]Während Ihr nicht in einen Kampf verwickelt seid, wird der Teleporteffekt Eurer Seelengestalt zu einem Sturmangriff, der Euer Ziel für 5 Sek. betäubt und Eure Seelengestalt dann beendet."}
MultiLanguageSpellData['de'][325066] = {name = "Taktiken der Wilden Jagd", additional_info = "[q0]Seelenbandefähigkeit\n[q]Erhöht Euren Schaden gegen Ziele mit mehr als 75% Gesundheit und Eure Heilung bei Zielen mit weniger als 35% Gesundheit um 10%.\n\n Wenn Eure Zauber und Fähigkeiten auf diese Weise verstärkt werden, wird Eure Bewegungsgeschwindigkeit für 5 Sek. um 15% erhöht.\n(700ms Abklingzeit)"}
MultiLanguageSpellData['de'][325067] = {name = "Horn der Wilden Jagd", additional_info = "[q0]Seelenbandefähigkeit\n[q]'Seelengestalt' erhöht die Bewegungsgeschwindigkeit von Verbündeten innerhalb von 40 Metern um 10%."}
MultiLanguageSpellData['de'][325068] = {name = "Dem Feind trotzen", additional_info = "[q0]Seelenbandefähigkeit\n[q]Wenn Ihr Euch vor Eurem Ziel befindet, verringern Eure Zauber und Fähigkeiten den Schaden, den es Euch zufügt, 2 Sek. lang um 3%."}
