MultiLanguageSpellData['de'][328275] = {name = "Wildes Mal", additional_info = "[q0]Pakt-Fähigkeit\n100 Meter Reichweite\nSofort\n[q]Ruft die Energie wilder Geister am Zielort hervor, die allen gegnerischen Zielen im Effektbereich (25% der Angriffskraft) Naturschaden zufügt und sie für 15 Sek. mit 'Wildes Mal' belegt.\n\n Während die wilden Geister aktiv sind, fügt jede Schadensfähigkeit, die Ihr oder Euer Begleiter gegen ein Ziel im Effektbereich einsetzt, bis zu 5 zusätzlichen Zielen in der Nähe (38.5% der Angriffskraft) Naturschaden zu."}
MultiLanguageSpellData['de'][328276] = {name = "Marsch der Bußfertigen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Sobald er 70% Gesundheit erreicht, zieht Denathrius alle Spielercharaktere in die Mitte des Raums und befördert sie dann nach außen zum Rand.\n\n Die Bewegungsgeschwindigkeit von mit 'Bürde der Sünde' belegten Spielercharakteren ist um 20% pro Stapel verringert und sie können keine Fähigkeiten einsetzen.\n\n Wenn Spielercharaktere sich Denathrius auf 16 Meter nähern, werden sie von 'Bürde der Sünde' erlöst."}
MultiLanguageSpellData['de'][328277] = {name = "Marsch der Bußfertigen", additional_info = nil}
