MultiLanguageSpellData['de'][328281] = {name = "Segen des Winters", additional_info = "[q0]Pakt-Fähigkeit\n{5% von Grundmana} {40 Meter Reichweite}\n{Sofort} {45 sek. Abklingzeit}\n[q]Segnet einen Verbündeten für 30 Sek. Dadurch verursachen seine Zauber und Fähigkeiten [((5 / 100 * Max(Angriffskraft, Zaubermacht) * (1 + Vielseitigkeit)))] Frostschaden und verringern die Bewegungsgeschwindigkeit von Gegnern um 5% sowie ihr Angriffstempo um 2%. Bis zu 10-mal stapelbar.\n\nSegen der Jahreszeiten: Wechselt nach dem Einsatz zum Frühling.\n(500ms Abklingzeit)"}
MultiLanguageSpellData['de'][328282] = {name = "Segen des Frühlings", additional_info = "[q0]Pakt-Fähigkeit\n{5% von Grundmana} {40 Meter Reichweite}\n{Sofort} {45 sek. Abklingzeit}\n[q]Segnet einen Verbündeten für 30 Sek. und erhöht so seine hervorgerufene Heilung um 15% sowie seine erhaltene Heilung um 30%.\n\nSegen der Jahreszeiten: Wechselt nach dem Einsatz zum Sommer."}
