MultiLanguageSpellData['de'][330896] = {name = "Straße der Prüfungen", additional_info = "100 Meter Reichweite\nSofort\n[q]Nachdem Ihr einen Gegner besiegt habt, erhaltet Ihr 20 Sek. lang 10% Bewegungsgeschwindigkeit. Dieser Effekt verstärkt sich, wenn Ihr einen mächtigen Gegner besiegt."}
MultiLanguageSpellData['de'][330897] = {name = "[q2]Greifende Tentakel", additional_info = "[q0]Animabonus\nSofort\n[q]Die ersten 3 erlittenen Nahkampfangriffe bei aktiver 'Baumrinde' oder 'Eisenborke' lösen bei Angreifern 'Wucherwurzeln' aus."}
MultiLanguageSpellData['de'][330898] = {name = "Furorfäuste", additional_info = "8 Meter Reichweite\n{Kanalisiert (Wirken in} {3 sek.) 24 sek. Abklingzeit}\n[q]Verprügelt alle Ziele vor Euch mit schnellen Faustangriffen, die Eurem Primärziel im Verlauf von 3 Sek. [5 * (120.75% der Angriffskraft)] körperlichen Schaden und bis zu 5 anderen Zielen im Verlauf von 3 Sek. [5 * (120.75% der Angriffskraft) * 50 / 100] Schaden zufügen."}
MultiLanguageSpellData['de'][330901] = {name = "Wirbelnder Kranichtritt", additional_info = "{2 Chi / 1% von Grundmana} {/ 25 Energie}\nKanalisiert (Wirken in 1.5 sek.)\n[q]Windläufer\n Ihr dreht Euch in der Luft, während Ihr Tritte ausführt, die bis zu 6 Gegnern innerhalb von 8 Metern im Verlauf von 1.5 Sek. [4 * (10% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] körperlichen Schaden zufügen.\n\n Der Schaden von 'Wirbelnder Kranichtritt' wird für jedes einzelne Ziel, das Ihr innerhalb der letzten 20 Sek. mit 'Tigerklaue', 'Blackout-Tritt' oder 'Tritt der aufgehenden Sonne' getroffen habt, um 18% erhöht.\n\nBraumeister, Nebelwirker\n Ihr dreht Euch in der Luft, während Ihr Tritte ausführt, die bis zu 6 Gegnern innerhalb von 8 Metern im Verlauf von 1.5 Sek. [4 * (10% der Angriffskraft)] körperlichen Schaden zufügen."}
MultiLanguageSpellData['de'][330902] = {name = "Nach oben teleportieren", additional_info = nil}
MultiLanguageSpellData['de'][330903] = {name = "Wirbelnder Kranichtritt", additional_info = "Sofort\n[q]Windläufer\nIhr dreht Euch in der Luft, während Ihr Tritte ausführt, die allen Gegnern innerhalb von 8 Metern im Verlauf von 1.5 Sek. [4 * (10% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] körperlichen Schaden zufügen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nBraumeister, Nebelwirker\nIhr dreht Euch in der Luft, während Ihr Tritte ausführt, die allen Gegnern innerhalb von 8 Metern im Verlauf von 1.5 Sek. [4 * (10% der Angriffskraft)] körperlichen Schaden zufügen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu."}
MultiLanguageSpellData['de'][330904] = {name = "[q2]Rottholzskarabäus", additional_info = "[q0]Animabonus\nSofort\n[q]Wenn 'Wucherwurzeln' aufgehoben wird, findet eine Explosion statt, die allen Gegnern in der Nähe (150% der Zaubermacht) Naturschaden zufügt."}
