MultiLanguageSpellData['de'][331642] = {name = "Niuzao den Schwarzen Ochsen beschwören", additional_info = "40 Meter Reichweite\nSofort 3 min Abklingzeit\n[q]Beschwört für 25 Sek. ein Abbild von Niuzao, dem Schwarzen Ochsen. Niuzao greift Euer Primärziel an und stampft mehrmals auf, was allen Gegnern in der Nähe [ Verbessertes Niuzao den Schwarzen Ochsen beschwören : (200% der Angriffskraft) Schaden und zusätzlich 0% des kürzlich entfernten gestaffelten Schadens zufügt / Schaden zufügt.]\n Während das Abbild aktiv ist, werden 25% des durch 'Staffeln' verzögerten Schadens stattdessen von Niuzao gestaffelt."}
MultiLanguageSpellData['de'][331643] = {name = "Xuen den Weißen Tiger beschwören", additional_info = "40 Meter Reichweite\nSofort 2 min Abklingzeit\n[q]Beschwört ein Abbild von Xuen, dem Weißen Tiger, das 25 Sek. lang bestehen bleibt. Xuen greift Euer Primärziel an und trifft 3 Gegner innerhalb von 10 Metern alle 1 Sek. mit Tigerblitzen, die (25.7% der Angriffskraft) Naturschaden verursachen."}
MultiLanguageSpellData['de'][331644] = {name = "Yu'lon die Jadeschlange beschwören", additional_info = "40 Meter Reichweite\nSofort 3 min Abklingzeit\n[q]Beschwört ein Abbild von Yu'lon, der Jadeschlange, das 25 Sek. lang bestehen bleibt. Yu'lon heilt Verbündete in der Nähe mit 'Himmlischer Atem' um (63% der Angriffskraft) Gesundheit."}
MultiLanguageSpellData['de'][331645] = {name = "Chi-Ji den Roten Kranich beschwören", additional_info = "40 Meter Reichweite\nSofort\n[q]Beschwört ein Abbild von Chi-Ji, das einen Nebelschwall auslöst, wenn Ihr 'Blackout-Tritt', 'Tritt der aufgehenden Sonne' oder 'Wirbelnder Kranichtritt' einsetzt, der bis zu 2 Verbündete um (0.1% der Zaubermacht) Gesundheit heilt und die Kosten und Zauberzeit Eures nächsten Einsatzes von 'Einhüllender Nebel' um 33% verringert. Diese Reduktion ist stapelbar.\n\n Chi-Jis Präsenz macht Euch immun gegen bewegungseinschränkende Effekte."}
