MultiLanguageSpellData['de'][331652] = {name = "Rollende Chiwellen", additional_info = "[q0]Animabonus\nSofort\n[q]Die Dauer von [ Braumeister : ' Niuzao den Schwarzen Ochsen beschwören ' / Windläufer : ' Xuen den Weißen Tiger beschwören ' / Chi-Ji den Roten Kranich beschwören : ' Chi-Ji den Roten Kranich beschwören ' / ' Yu'lon die Jadeschlange beschwören ' ] ist um 50% erhöht und die Beschwörung wird eingesetzt, wenn Ihr zum ersten Mal pro Stock einen Kampf beginnt."}
