MultiLanguageSpellData['de'][332169] = {name = "Wutanfall", additional_info = "{Wirken in} {2 sek. 10 sek. Abklingzeit}\n[q]Stößt ein kehliges Heulen aus, das 12 Sek. lang den verursachten Schaden um 50% und die Bewegungsgeschwindigkeit um 30% erhöht."}
