MultiLanguageSpellData['de'][334406] = {name = "Ewiger Phalynx des Mutes", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Um eines dieser funkelnden Reittiere zu schmieden, sind viele Barren Güldenit erforderlich. Doch allein ihr Anblick ist die in das Sammeln des Güldenits investierte Zeit schon wert.\"\nPakt:\nKyrianer\nZone:\nBastion"}
MultiLanguageSpellData['de'][334407] = {name = "Adliger Habitus", additional_info = "Sofort\nReagenzien:\nKommode des Adligen\n[q]Nach Erhalt: Kleidet Euch für 15 Min. wie ein Höfling des Hauses Redelav. Darauf wird zwar kaum jemand hereinfallen, aber dafür sehr Ihr höchst edel aus. Kann nur im Freien in den Schattenlanden verwendet werden."}
