MultiLanguageSpellData['de'][335931] = {name = "Banner des Eroberers", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Erhebt das Banner des Eroberers, was Euch und Euren 2 nächsten Verbündeten 1550 Meisterschaft und um 30% erhöhte Bewegungsgeschwindigkeit gewährt sowie verhindert, dass die Bewegungsgeschwindigkeit unter 100% verringert wird. Hält 15 Sek. lang an.\n\nErzeugt 4 Wut pro Sekunde."}
MultiLanguageSpellData['de'][335932] = {name = "Todeschakram", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Wirft ein tödliches Chakram auf Euer aktuelles Ziel, das rasch 7-mal (31.6% der Angriffskraft) Schattenschaden verursacht und auf weitere Ziele in der Nähe überspringt. Von 'Todeschakram' getroffene Ziele erleiden 10 Sek. lang 10% mehr körperlichen Schaden durch Euch und Eure Begleiter.\n\n Jedes Mal, wenn das Chakram Schaden verursacht, wird sein Schaden um 15% erhöht und Ihr erzeugt 3 Fokus."}
MultiLanguageSpellData['de'][335933] = {name = "Monströse Gliedmaße", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Frost\nLässt eine zusätzliche Gliedmaße wachsen, die allen Gegnern in der Nähe im Verlauf von 12 Sek. [(28.4% der Angriffskraft) * 13] Schattenschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Alle 1 Sek. wird ein Gegner zu Eurer Position gezogen, wenn er weiter als 8 Meter von Euch entfernt ist. Die monströse Gliedmaße kann denselben Gegner nur einmal alle 4 Sek. heranziehen.\n\n Verleiht Euch sofort 'Raureif' und erneut alle 6 Sek. danach.\n\nUnheilig\nLässt eine zusätzliche Gliedmaße wachsen, die allen Gegnern in der Nähe im Verlauf von 12 Sek. [(28.4% der Angriffskraft) * 13] Schattenschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Alle 1 Sek. wird ein Gegner zu Eurer Position gezogen, wenn er weiter als 8 Meter von Euch entfernt ist. Die monströse Gliedmaße kann denselben Gegner nur einmal alle 4 Sek. heranziehen.\n\n Verleiht Euch sofort 'Runenverderbnis' und erneut alle 6 Sek. danach.\n\nBlut\nLässt eine zusätzliche Gliedmaße wachsen, die allen Gegnern in der Nähe im Verlauf von 12 Sek. [(28.4% der Angriffskraft) * 13] Schattenschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Alle 1 Sek. wird ein Gegner zu Eurer Position gezogen, wenn er weiter als 8 Meter von Euch entfernt ist. Die monströse Gliedmaße kann denselben Gegner nur einmal alle 4 Sek. heranziehen.\n\n Verleiht Euch sofort 3 Aufladungen von 'Knochenschild' und erneut alle 6 Sek. danach."}
MultiLanguageSpellData['de'][335934] = {name = "Futter für die Flamme", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Eure Schaden verursachenden Fähigkeiten haben eine Chance, für 25 Sek. einen Dämon aus dem Theater der Schmerzen herbeizurufen. 'Gleve werfen' fügt dem Dämon tödlichen Schaden zu. Beim Tod explodiert er, fügt Gegnern in der Nähe (192.5% der Angriffskraft) Schatten schaden zu und heilt Euch um 20% Eurer maximalen Gesundheit. Die Explosion fügt Zielen über 5 Ziele hinaus verringerten Schaden zu."}
MultiLanguageSpellData['de'][335935] = {name = "Adaptiver Schwarm", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Befehligt einen Schwarm, der im Verlauf von 12 Sek. ein Ziel um (157.5% der Zaubermacht) Gesundheit heilt oder ihm (150% der Zaubermacht) Schattenschaden zufügt und die Effektivität Eurer regelmäßigen Effekte beim Ziel um 25% erhöht.\n\n Bei Ablauf sucht sich der Schwarm bis zu 3-mal ein neues Ziel, wobei er versucht, abwechselnd zwischen einem Verbündeten und einem Gegner überzuspringen."}
MultiLanguageSpellData['de'][335936] = {name = "Todesgeboren", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Verwandelt Euch für 25 Sek. in einen mächtigen Skelettmagier.\n\n Während Ihr in der Gestalt des Skelettmagiers seid, treffen Eure Fähigkeiten 'Frostblitz', 'Feuerball' und 'Arkanschlag' bis zu 2 Gegner in der Nähe Eures Ziels und Euer Zauberschaden ist um 15% erhöht."}
MultiLanguageSpellData['de'][335937] = {name = "Knochenstaubgebräu", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Schleudert ein aus den Knochen Eurer Gegner hergestelltes Gebräu auf den Boden, das alle getroffenen Ziele für 10 Sek. bedeckt. Eure Fähigkeiten haben eine Chance von 50%, sich mit 40% Effektivität ein zweites Mal als Schattenschaden oder Heilung auf das Ziel auszuwirken.\n\n [ Nebelwirker : 'Nebelschwall' heilt alle Ziele, bei denen Euer Knochenstaubgebräu aktiv ist, um zusätzlich (42% der Angriffskraft) Gesundheit / Braumeister : 'Tigerklaue' und 'Fasshieb' verringern die Abklingzeiten Eurer Gebräue um zusätzlich 1 Sek., wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist / Windläufer : 'Wirbelnder Kranichtritt' erstattet 1 Chi, wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist ]"}
MultiLanguageSpellData['de'][335938] = {name = "Gefrierender Impuls", additional_info = "Sofort\n[q]Mort stößt alle 5 Sek. Frostschleim aus, der Gegnern innerhalb von 10 Metern 0 Frostschaden zufügt, sie mit 'Gefrierende Gliedmaßen' belegt und einen Bereich von 'Gefrierender Boden' hinterlässt."}
MultiLanguageSpellData['de'][335939] = {name = "Hammer des Bezwingers", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Wirft einen Hammer auf Euer Ziel, der (136% der Zaubermacht) Schattenschaden verursacht und Euren nächsten Einsatz von [ Vergeltung : 'Urteil des Templers' ermächtigt, sodass automatisch 'Göttlicher Sturm' ] [ Heilig : 'Wort der Herrlichkeit' ermächtigt, sodass automatisch 'Licht der Morgendämmerung' /\n\nSchutz\n'Wort der Herrlichkeit' ermächtigt, sodass automatisch 'Schild der Rechtschaffenen' ] mit 25% höherer Effektivität ausgelöst wird.\n\nErzeugt 1 Heilige Kraft."}
MultiLanguageSpellData['de'][335940] = {name = "Gezackter Knochenstachel", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Steckt einen Knochenstachel in das Ziel, der (132% der Angriffskraft) körperlichen Schaden sowie alle 3 Sek. (11% der Angriffskraft) Blutungsschaden verursacht, bis das Ziel stirbt oder den Kampf verlässt.\n\n Wenn das Ziel stirbt wird, wird 1 Aufladung erstattet.\n\nGewährt 1 Combopunkt plus 1 weiteren pro aktivem Knochenstachel."}
MultiLanguageSpellData['de'][335941] = {name = "Urzeitliche Welle", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Wiederherstellung\nÜberzieht Euer Ziel mit einer urzeitlichen Welle, die (65% der Zaubermacht) Schattenschaden verursacht und einen Gegner mit 'Flammenschock' belegt oder einen Verbündeten um (65% der Zaubermacht) Gesundheit heilt und ihn mit 'Springflut' belegt.\n\n Euer nächster Einsatz von 'Welle der Heilung' trifft zusätzlich alle Ziele, die mit Eurem Effekt 'Springflut' belegt sind, und verursacht dabei 60% der normalen Heilung.\n\nVerstärkung\nÜberzieht Euer Ziel mit einer urzeitlichen Welle, die (65% der Zaubermacht) Schattenschaden verursacht und einen Gegner mit 'Flammenschock' belegt oder einen Verbündeten um (65% der Zaubermacht) Gesundheit heilt.\n\n Euer nächster Einsatz von 'Blitzschlag' trifft zusätzlich alle Ziele, die mit Eurem Effekt 'Flammenschock' belegt sind, und verursacht dabei 150% des normalen Schadens.\n\nElementar\nÜberzieht Euer Ziel mit einer urzeitlichen Welle, die (65% der Zaubermacht) Schattenschaden verursacht und einen Gegner mit 'Flammenschock' belegt oder einen Verbündeten um (65% der Zaubermacht) Gesundheit heilt.\n\n Euer nächster Einsatz von 'Lavaeruption' trifft zusätzlich alle Ziele, die mit Eurem Effekt 'Flammenschock' belegt sind, und verursacht dabei 80% des normalen Schadens."}
MultiLanguageSpellData['de'][335942] = {name = "Dezimierungsblitz", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Dämonologie, Dämonologie (Zerstörungshexenmeister)\nSchleudert Blitze aus dezimierender Magie auf Euer Ziel, die [4 * (34.5% der Zaubermacht)] Schattenschaden verursachen und den Schaden Eurer nächsten 3 Einsätze von 'Dämonenblitz' um 100% erhöhen.\n\n Sowohl der Schaden von 'Dezimierungsblitz' als auch der Bonus für 'Dämonenblitz' steigt mit abnehmender Gesundheit Eures Ziels an.\n\nZerstörung, Zerstörung (Dämonologiehexenmeister)\nSchleudert Blitze aus dezimierender Magie auf Euer Ziel, die [4 * (34.5% der Zaubermacht)] Schattenschaden verursachen und den Schaden Eurer nächsten 3 Einsätze von 'Verbrennen' um 100% erhöhen.\n\n Sowohl der Schaden von 'Dezimierungsblitz' als auch der Bonus für 'Verbrennen' steigt mit abnehmender Gesundheit Eures Ziels an.\n\nGebrechen\nSchleudert Blitze aus dezimierender Magie auf Euer Ziel, die [4 * (34.5% der Zaubermacht)] Schattenschaden verursachen und den Schaden Eurer nächsten 3 Einsätze von um 100% erhöhen.\n\n Sowohl der Schaden von 'Dezimierungsblitz' als auch der Bonus für steigt mit abnehmender Gesundheit Eures Ziels an."}
