MultiLanguageSpellData['de'][336036] = {name = "Markzahn", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Der unersättliche Appetit von Markzahn, Nachkomme von Knochenzahn, wurde von Amarth dem Ernter geschätzt, auch wenn er die Experimente des sadistischen Kommandanten störte.\"\nBeute:\nNalthor der Eisbinder\nZone:\nDie Nekrotische Schneise (Mythisch)\n\nBeute:\nSchatz des Herausforderers\nZone:\nDie Nekrotische Schneise"}
MultiLanguageSpellData['de'][336037] = {name = "Schneide des Vergessens", additional_info = "10 Meter Reichweite\nWirken in 2 sek.\n[q]Greift alle Gegner in einem kegelförmigen Bereich an und verursacht körperlichen Schaden."}
MultiLanguageSpellData['de'][336038] = {name = "Kahler Fledderflügel", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Fledderflügel sind notwendig für den Kreislauf des Lebens in den Schattenlanden. In der rauen Umgebung von Maldraxxus sind sie sowohl Räuber als auch Beute.\"\nZone:\nMaldraxxus"}
MultiLanguageSpellData['de'][336039] = {name = "Grauenhafter Fledderflügel", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Fledderflügel von Maldraxxus werden für ihre Fähigkeit, mühelos in den Himmel der Schattenlande aufzusteigen, sehr geschätzt. Ihre Reiter sind dadurch in der Lage, ihre Verbündeten aus der Luft zu unterstützen oder ihre Gegner von oben aus zu überrumpeln.\"\nPaktfeature:\nDer Gluthof\nPakt:\nVenthyr\n\nPaktfeature:\nKonservatorium der Königin\nPakt:\nNachtfae\n\nPaktfeature:\nPfad des Aufstiegs\nPakt:\nKyrianer\n\nPaktfeature:\nMonstrositätenfabrik\nPakt:\nNekrolords"}
MultiLanguageSpellData['de'][336040] = {name = "Herzpilzblähungen", additional_info = "Sofort\n[q]Durch den Verzehr eines Herzpilzes von Blähungen geplagt, was die Bewegungsgeschwindigkeit 5 Sek. lang um 65% verringert."}
MultiLanguageSpellData['de'][336041] = {name = "Knochenvernähter Fleischroc", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Nur erfahrene Fleischnäher, die ihre meisterhafte Beherrschung der Magien von Maldraxxus unter Beweis gestellt haben, sind mächtig genug, einen Todesroc dieser Größe zu erschaffen.\"\nBeruf:\nMonstrositätenflickerei\nZone:\nMaldraxxus"}
MultiLanguageSpellData['de'][336042] = {name = "Bulliger Todesroc", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Todesrocs sind Monstrositäten, zusammengeflickt aus Eingeweiden, Knochen und Organen, die nicht zum Bau von Soldaten im Haus der Konstrukte gebraucht wurden.\"\nBeute von:\nVioletter Fehler\nZone:\nMaldraxxus"}
MultiLanguageSpellData['de'][336043] = {name = "Geistpilzschwindel", additional_info = "Sofort\n[q]Leidet durch den Verzehr eines Geistpilzes an Schwindel, was die Trefferchance 4 Sek. lang um 50% verringert."}
