MultiLanguageSpellData['de'][337041] = {name = "Wissen des Ritualisten", additional_info = "Sofort\n[q]Gewährt dem Träger die Fähigkeit, niedrigstufige Bindungszauber im Haus der Rituale zu umgehen."}
MultiLanguageSpellData['de'][337042] = {name = "Dornentransformation", additional_info = "{Wirken in} {1 sek. 1 sek. Abklingzeit}\n[q]Nimmt das Aussehen eines Bären an."}
MultiLanguageSpellData['de'][337043] = {name = "Schwärmender Nebel", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Ein dichter Nebel umhüllt Euch für 8 Sek. und erhöht Euer Ausweichen um 10%.\n\n Fügt Gegnern innerhalb von 10 Metern alle 1 Sek. (20% der Angriffskraft) Schattenschaden zu. Jedes Mal, wenn der Effekt Schaden verursacht, erhaltet Ihr 3 Runenmacht, bis zu maximal 15 Runenmacht. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu."}
MultiLanguageSpellData['de'][337044] = {name = "Sündhaftes Brandzeichen", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Brandmarkt einen Gegner mit dem Zeichen der Venthyr, das sein Nahkampfangriffstempo um 30% und sein Zaubertempo um 30% verringert. Verursacht außerdem im Verlauf von 8 Sek. (338% der Angriffskraft) Schattenschaden.\n\n Beim Aktivieren von 'Metamorphose' werden alle Gegner in der Nähe mit 'Sündhaftes Brandzeichen' belegt."}
MultiLanguageSpellData['de'][337045] = {name = "Unersättliche Raserei", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Von Euch eingesetzte Druidenzauber erhöhen 20 Sek. lang Euren Schaden und Eure Heilung um 2% sowie Euer Tempo um 1%. Dieser Effekt ist stapelbar.\n\n Wenn Ihr 2 Sek. lang untätig bleibt, überwältigt Euch die Raserei, was pro Stapel 1% Eurer Gesundheit aufzehrt, Euch für 1 Sek. betäubt und den Effekt beendet."}
MultiLanguageSpellData['de'][337046] = {name = "Schinderschuss", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Feuert einen Schuss auf Euren Gegner ab, der ihm (50% der Angriffskraft) Schattenschaden zufügt und ihn bluten lässt, was ihm im Verlauf von 18 Sek. zusätzlich (112.5% der Angriffskraft) Schattenschaden zufügt. Jedes Mal, wenn 'Schinderschuss' Schaden verursacht, habt Ihr eine Chance von 15%, 'Mal des Schinders' zu erhalten, wodurch Euer nächster Einsatz von 'Tödlicher Schuss' kostenlos wird, gegen jedes Ziel unabhängig von seiner aktuellen Gesundheit eingesetzt werden kann und 25% mehr Schaden verursacht."}
MultiLanguageSpellData['de'][337047] = {name = "Nekrotischer Hauch", additional_info = "300 Meter Reichweite\n{Wirken in} {3 sek. 5 sek. Abklingzeit}\n[q]Fügt allen Gegnern vor dem Zaubernden 40 Schattenschaden zu und verringert ihre erhaltene Heilung 6 Sek. lang um 50%."}
MultiLanguageSpellData['de'][337048] = {name = "Spiegel der Qual", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Beschwört 3 Spiegel, die den Gegner 25 Sek. lang quälen. Immer wenn das Ziel angreift, einen Zauber oder eine Fähigkeit einsetzt, wird ein Spiegel verbraucht, der dem Gegner dabei (60% der Zaubermacht) Schattenschaden zufügt und sein Zaubertempo sowie seine Bewegungsgeschwindigkeit um 15% verringert. Dieser Effekt kann nur einmal alle 6 Sek. ausgelöst werden.\n\n Der letzte Spiegel fügt dem Gegner (151% der Zaubermacht) Schattenschaden zu, macht ihn 4 Sek. lang bewegungsunfähig und bringt ihn währenddessen zum Schweigen.\n\n Wenn ein Spiegel verbraucht wird, [ Arkan : erhaltet Ihr den Effekt 'Freizaubern' ] [ Feuer : wird die Abklingzeit von 'Feuerschlag' um 6 Sek. verringert ] [ Frost : erhaltet Ihr 'Hirnfrost' ]"}
MultiLanguageSpellData['de'][337049] = {name = "Unterkühlende Welle", additional_info = "200 Meter Reichweite\nWirken in 3 sek.\n[q]Fügt Gegnern innerhalb von 8 Metern 5 Frostschaden sowie alle 2 Sek. 1 Frostschaden zu und verringert ihre Bewegungsgeschwindigkeit um 50%. Hält 8 Sek. lang an."}
MultiLanguageSpellData['de'][337050] = {name = "Ascheweihung", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Weiht den Zielbereich für 30 Sek. Gegner innerhalb des Bereichs erleiden bis zu [(55% der Zaubermacht) * 30 / 2] Schattenschaden und Verbündete werden um bis zu [(36% der Zaubermacht) * 30 / 2] Gesundheit geheilt. Die Werte verringern sich bei mehr als 5 Zielen.\n\n Innerhalb der Weihung könnt Ihr 'Hammer des Zorns' gegen jedes beliebige Ziel einsetzen und die Fähigkeit verursacht 100% mehr Schaden."}
MultiLanguageSpellData['de'][337051] = {name = "Gedankenspiele", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Greift den Verstand eines Gegners an, fügt ihm [(300% der Zaubermacht) * 100 / 100] Schattenschaden zu und kehrt seine Wahrnehmung der Realität für kurze Zeit um.\n\n [ Schatten : Für 5 Sek. heilen die nächsten [(Schattenzaubermacht * 450 / 100) * (1 + Vielseitigkeit) * 100 / 100] Schaden, die dieser Gegner verursacht, sein Ziel und die nächsten [(Schattenzaubermacht * 450 / 100) * (1 + Vielseitigkeit) * 100 / 100] Heilung, die er hervorruft, werden seinem Ziel als Schaden zugefügt.\n\nUmgekehrter Schaden und umgekehrte Heilung erzeugen bis zu 20 Wahnsinn. /\n\nDisziplin, Heilig\nFür 5 Sek. heilen die nächsten [(Schattenzaubermacht * 450 / 100) * (1 + Vielseitigkeit) * 100 / 100] Schaden, die dieser Gegner verursacht, sein Ziel und die nächsten [(Schattenzaubermacht * 450 / 100) * (1 + Vielseitigkeit) * 100 / 100] Heilung, die er hervorruft, werden seinem Ziel als Schaden zugefügt.\n\nUmgekehrter Schaden und umgekehrte Heilung stellen bis zu 4% Mana wieder her. ]"}
MultiLanguageSpellData['de'][337052] = {name = "Geißelung", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Peitscht das Ziel und fügt ihm so (50% der Angriffskraft) Schattenschaden zu. Zusätzlich löst jeder innerhalb von 12 Sek. verbrauchte Combopunkt einen weiteren Peitschenhieb aus, der (10% der Angriffskraft) Schaden verursacht. Wenn Ihr Schaden mit 'Geißelung' verursacht, wird Euer Tempo um 1% erhöht. Dieser Effekt hält nach Ende der Qual des Ziels noch 12 Sek. lang an."}
MultiLanguageSpellData['de'][337053] = {name = "Unterkühlende Welle", additional_info = "200 Meter Reichweite\nSofort\n[q]Fügt Gegnern innerhalb von 8 Metern 5 Frostschaden sowie alle 2 Sek. 1 Frostschaden zu und verringert ihre Bewegungsgeschwindigkeit um 50%. Hält 8 Sek. lang an."}
MultiLanguageSpellData['de'][337054] = {name = "Kettenernte", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Schleudert eine Animawelle auf das Ziel, die auf weitere Ziele in der Nähe überspringt. Fügt bis zu 5 Gegnern (205% der Zaubermacht) Schattenschaden zu und heilt bis zu 5 Verbündete um (315% der Zaubermacht) Gesundheit.\n\n Die Abklingzeit von 'Kettenernte' wird pro kritisch getroffenem Ziel um 5 Sek. verringert. [ Meisterschaft: Elementarüberladung : Erzeugt pro getroffenem oder geheiltem Ziel 3 Mahlstrom ]"}
MultiLanguageSpellData['de'][337055] = {name = "Drohende Katastrophe", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Ruft eine Wolke chaotischer Anima herbei, die sich zum gegnerischen Ziel bewegt und Gegnern in ihrer Bahn (25.3% der Zaubermacht) Schattenschaden zufügt. Wenn die Anima das Ziel erreicht, explodiert sie, belegt das Ziel entweder mit 'Fluch der Schwäche' oder mit 'Fluch der Sprachen' und fügt allen Gegnern in der Nähe im Verlauf von 12 Sek. (138% der Zaubermacht) Schattenschaden zu."}
MultiLanguageSpellData['de'][337056] = {name = "Verurteilen", additional_info = "[q0]Pakt-Fähigkeit\nSofort\n[q]Erlernt die Fähigkeit 'Verurteilen', die 'Hinrichten' ersetzt. 'Verurteilen' verursacht Schattenschaden und kann gegen Gegner mit über 80% oder unter 20% Gesundheit eingesetzt werden. Das Ziel wird geschwächt, was einen Teil des Schadens verhindert, den dieses Ziel Euch zufügen würde."}
MultiLanguageSpellData['de'][337057] = {name = "[q5]Relikt der dämonischen Synergie", additional_info = "Runenschnitzmacht\nCa. 3 Procs pro Minute\n[q2]Wenn Ihr oder Euer Primärdämon Schaden verursacht, besteht eine Chance, dass der jeweils andere 15 Sek. lang eine Schadenserhöhung von [ Dämonologie : 15% /\n\nGebrechen, Zerstörung\n10% ] erhält.\n[q]Runenschnitzen: Kopf, Schulter, Rücken\n[q]Quelle: Schlachtzugbeute: Generäle der Steinlegion\n[q]Benötigt: Hexenmeister"}
