MultiLanguageSpellData['de'][337476] = {name = "Umwölkter Fokus", additional_info = "Sofort\n[q]Heilungen mit 'Einhüllender Nebel' oder 'Beleben', während Ihr 'Beruhigender Nebel' kanalisiert, erhöhen die verursachte Heilung der beiden Fähigkeiten um 20% und verringern ihre Manakosten um 20%. Bis zu 3-mal stapelbar.\n\n Wenn das Kanalisieren von 'Beruhigender Nebel' endet, wird dieser Effekt aufgehoben."}
MultiLanguageSpellData['de'][337477] = {name = "[q5]X'anshi, Rückkehr von Erzbischof Benedictus", additional_info = "Runenschnitzmacht\n[q2]Wenn Euer Geist der Erlösung abläuft, werdet Ihr mit bis zu 100% Gesundheit wiederbelebt, abhängig davon, wie effektiv Ihr als Geist der Erlösung wart. Nach Eurer Wiederbelebung kann der Geist der Erlösung 10 Min. lang nicht erneut ausgelöst werden.\n[q]Runenschnitzen: Beine, Rücken\n[q]Quelle: Weltbossbeute: Valinor, das Licht der Äonen\n[q]Benötigt: Priester (Heilig)"}
